    ('0025b0ba-fd74-4c08-96e3-acc17956aa44'::uuid, 'card_description', 'Excavated ground at the foot of Mount Meron exceeded six acres. Khirbet Shema holds a large Jewish village of the Roman and Byzantine periods, with its synagogue and mausoleum.', NULL, 'teaser-card-s032-rollback:0025b0ba-fd74-4c08-96e3-acc17956aa44:card_description', 'rollback of teaser-card-s032: card_description None restored on Horvat Shema', '931faeefea9e462239134319d5199f81092bde9548b2f3c2dc77ef377b6859c4|d656109b8605c184ef1a99a800d9c94f6f9ddb2af2dae53e68ec97018ad4422e|d656109b8605c184ef1a99a800d9c94f6f9ddb2af2dae53e68ec97018ad4422e', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Excavated ground at the foot of Mount Meron exceeded six acres. Khirbet Shema holds a large Jewish village of the Roman and Byzantine periods, with its synagogue and mausoleum."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the excavated ground at the foot of Mount Meron exceeded six acres [S1, S4]; Khirbet Shema holds the ruins of a large Jewish village of the Roman and Byzantine periods [S2]; the village includes an ancient synagogue [S2]; the village includes a mausoleum [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Khirbet Shema (Horvat Shema) is an archaeological site in Israel, at the foot of Mount Meron [SUPPORTED: https://en.wikipedia.org/wiki/Khirbet_Shema]; The excavated area at the site exceeded six acres [SUPPORTED: https://en.wikipedia.org/wiki/Khirbet_Shema]; The site holds the ruins of a large Jewish village [SUPPORTED: https://en.wikipedia.org/wiki/Khirbet_Shema]; That village dates to the Roman and Byzantine periods [SUPPORTED: https://en.wikipedia.org/wiki/Khirbet_Shema]; The site includes a synagogue and a mausoleum [SUPPORTED: https://en.wikipedia.org/wiki/Khirbet_Shema]"}]'::jsonb),
    ('003428cd-6046-41c9-a687-a8a2b392e19d'::uuid, 'card_description', 'At Church Stoke in eastern Montgomeryshire, a steep-sided volcanic hill rises to 370 metres. Roundton Hill has been a nature reserve of the Montgomeryshire Wildlife Trust since 1985.', NULL, 'teaser-card-s032-rollback:003428cd-6046-41c9-a687-a8a2b392e19d:card_description', 'rollback of teaser-card-s032: card_description None restored on Roundton Hill', '2d20140e27c0721c92dba461df9883426aabb9bff2ef5c398403685a59752939|bd9ad8deaaacdf1069717cbf94b394bd1c93513eda3a960877f25879913b621c|bd9ad8deaaacdf1069717cbf94b394bd1c93513eda3a960877f25879913b621c', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "At Church Stoke in eastern Montgomeryshire, a steep-sided volcanic hill rises to 370 metres. Roundton Hill has been a nature reserve of the Montgomeryshire Wildlife Trust since 1985."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the hill is a steep-sided volcanic hill [S1]; it rises to 370 metres [S1]; it is in eastern Montgomeryshire [S1]; it stands at Church Stoke [S1]; it has been managed as a nature reserve by the Montgomeryshire Wildlife Trust since 1985 [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Roundton Hill is a rounded, steep-sided hill [SUPPORTED: https://en.wikipedia.org/wiki/Roundton_Hill]; Roundton Hill rises to 370 metres (1,210 feet) [SUPPORTED: https://en.wikipedia.org/wiki/Roundton_Hill]; Roundton Hill is volcanic in origin [SUPPORTED: https://en.wikipedia.org/wiki/Roundton_Hill]; Roundton Hill lies in the easternmost part of old Montgomeryshire, now in Powys, Wales [SUPPORTED: https://en.wikipedia.org/wiki/Roundton_Hill]; Roundton Hill is at Church Stoke, on the English border [SUPPORTED: https://en.wikipedia.org/wiki/Roundton_Hill]; Roundton Hill is managed as a nature reserve by the Montgomeryshire Wildlife Trust [SUPPORTED: https://en.wikipedia.org/wiki/Roundton_Hill]; The Montgomeryshire Wildlife Trust acquired Roundton Hill in 1985, so it has been the Trust''s nature reserve since 1985 [SUPPORTED: https://en.wikipedia.org/wiki/Roundton_Hill]"}]'::jsonb),
    ('0047ae41-af8e-44e1-b196-4035f5860554'::uuid, 'card_description', 'Gonnus stood on the north side of the Peneius, near the entrance of the only two passes by which an enemy could enter Thessaly from the north. Xerxes I''s army came that way.', NULL, 'teaser-card-s032-rollback:0047ae41-af8e-44e1-b196-4035f5860554:card_description', 'rollback of teaser-card-s032: card_description None restored on Gonnus', '7b40c3741667fa329bfa075109ebaa800c4618be2b012a98e085f1ddad27b593|0402574baef52c15ad7def4e353a42a6afa2f70c5c297809acf3e5a2e71cc05b|0402574baef52c15ad7def4e353a42a6afa2f70c5c297809acf3e5a2e71cc05b', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Gonnus stood on the north side of the Peneius, near the entrance of the only two passes by which an enemy could enter Thessaly from the north. Xerxes I''s army came that way."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Gonnus stood on the northern side of the Peneius [S3]; it stood near the entrance of the only two passes by which an enemy could enter Thessaly from the north [S3]; Xerxes I''s army entered Thessaly by that route [S4, S5]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Gonnus was a town and polis (city-state) [SUPPORTED: https://en.wikipedia.org/wiki/Gonnus]; Gonnus belonged to the Perrhaebi in ancient Thessaly [SUPPORTED: https://en.wikipedia.org/wiki/Gonnus]; Gonnus stood on the northern side of the Peneius [SUPPORTED: https://en.wikipedia.org/wiki/Gonnus]; It stood near the entrance of the only two passes by which an enemy could enter Thessaly from the north [SUPPORTED: https://en.wikipedia.org/wiki/Gonnus]; The army of Xerxes I entered Thessaly by that route [SUPPORTED: https://en.wikipedia.org/wiki/Gonnus]"}]'::jsonb),
    ('006294ae-548b-40ac-9271-03a017df7217'::uuid, 'card_description', 'A causeway links El Tintal to El Mirador, the larger site. About 25 km northeast of Carmelita, El Tintal is the second-largest in the Mirador Basin, among the four largest in northern Petén.', NULL, 'teaser-card-s032-rollback:006294ae-548b-40ac-9271-03a017df7217:card_description', 'rollback of teaser-card-s032: card_description None restored on El Tintal', 'b8186189290414a5d63e604a67b33cea79513a6e038bb7e65f90a08272462df8|0a8179eae6c1295bc913120593d46565bd6a2efff84f7d313ffc3f26cf5747a4|0a8179eae6c1295bc913120593d46565bd6a2efff84f7d313ffc3f26cf5747a4', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "A causeway links El Tintal to El Mirador, the larger site. About 25 km northeast of Carmelita, El Tintal is the second-largest in the Mirador Basin, among the four largest in northern Petén."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "a causeway links El Tintal to El Mirador [S3]; El Mirador is the larger of the two sites [S2]; El Tintal lies about 25 km northeast of Carmelita [S1]; El Tintal is the second-largest site in the Mirador Basin [S2]; El Tintal ranks among the four largest sites in northern Peten [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "El Tintal is a Maya archaeological site in the northern Peten region of Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/El_Tintal]; A causeway linked El Tintal to El Mirador [SUPPORTED: https://en.wikipedia.org/wiki/El_Tintal]; El Mirador is the larger site [SUPPORTED: https://en.wikipedia.org/wiki/El_Tintal]; El Tintal lies about 25 km northeast of Carmelita [SUPPORTED: https://en.wikipedia.org/wiki/El_Tintal]; El Tintal is the second largest site in the Mirador Basin [SUPPORTED: https://en.wikipedia.org/wiki/El_Tintal]; El Tintal is among the four largest sites in northern Peten [SUPPORTED: https://en.wikipedia.org/wiki/El_Tintal]"}]'::jsonb),
    ('0088c7e5-4a78-4b89-945d-3d5c787818e5'::uuid, 'card_description', 'Near Linares, Castulo was occupied from the Neolithic period and by the 6th century BC was the chief settlement of the Oretani. Roman sources say the princess Himilce married Hannibal.', NULL, 'teaser-card-s032-rollback:0088c7e5-4a78-4b89-945d-3d5c787818e5:card_description', 'rollback of teaser-card-s032: card_description None restored on Castulo', '81a565a1913ddf827560b4bef97f77fe62aa04ac15bedff1145119bdfdab2ca5|71b847ee2f0f8a78afc10d9f0021596a834776e5ef466e0087a8178d909f87da|71b847ee2f0f8a78afc10d9f0021596a834776e5ef466e0087a8178d909f87da', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Near Linares, Castulo was occupied from the Neolithic period and by the 6th century BC was the chief settlement of the Oretani. Roman sources say the princess Himilce married Hannibal."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Castulo is near modern Linares [S1]; it was occupied from the Neolithic period [S1]; by the 6th century BC it was the chief settlement of the Oretani people [S2]; according to Roman sources, the princess Himilce married Hannibal [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Castulo is an Iberian town (settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Castulo]; Castulo lies in the province of Jaen, in south-central Spain [SUPPORTED: https://en.wikipedia.org/wiki/Castulo]; Castulo lies near modern Linares [SUPPORTED: https://en.wikipedia.org/wiki/Castulo]; Castulo was occupied from the Neolithic period [SUPPORTED: https://en.wikipedia.org/wiki/Castulo]; Castulo was the chief seat (town) of the Oretani [SUPPORTED: https://en.wikipedia.org/wiki/Castulo]; The Oretani were settled there from the 6th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Castulo]; The princess Himilce married Hannibal [SUPPORTED: https://en.wikipedia.org/wiki/Castulo]; Roman sources record that Hannibal married a woman from Castulo [SUPPORTED: https://en.wikipedia.org/wiki/Imilce]; A Roman author names that woman Imilce (Himilce) [SUPPORTED: https://en.wikipedia.org/wiki/Imilce]"}]'::jsonb),
    ('00cb2c16-2b30-42ce-aeb0-b258761ea754'::uuid, 'card_description', 'Where the Exe and Lowman meet, Stone Age flint tools mark Tiverton, the town on two fords. Cranmore Castle, over 15 acres, possibly a livestock enclosure, market site or tribal oppidum.', NULL, 'teaser-card-s032-rollback:00cb2c16-2b30-42ce-aeb0-b258761ea754:card_description', 'rollback of teaser-card-s032: card_description None restored on Tiverton, Devon', 'dd1eaf16354cf6d35e5ddef811a5e56b7de4c40eba4d2e86dc1784d8a3a30f76|3d9ff47e5fc947907e5c18ea3f1b89e4f142b30fefa820d4d23c9780e85e4d59|3d9ff47e5fc947907e5c18ea3f1b89e4f142b30fefa820d4d23c9780e85e4d59', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Where the Exe and Lowman meet, Stone Age flint tools mark Tiverton, the town on two fords. Cranmore Castle, over 15 acres, possibly a livestock enclosure, market site or tribal oppidum."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Exe and Lowman meet there [S1]; Stone Age flint tools were found at Tiverton [S1]; its name means the town on two fords [S4]; Cranmore Castle covers over 15 acres [S2]; Cranmore Castle''s function was possibly a livestock enclosure, a market site or a tribal oppidum [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Cranmore Castle is an Iron Age earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Cranmore_Castle]; Cranmore Castle stands on a hillside above the Devon town of Tiverton [SUPPORTED: https://en.wikipedia.org/wiki/Cranmore_Castle]; Cranmore Castle is widely described as an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Cranmore_Castle]; Cranmore Castle covers over 15 acres (61,000 square metres) [SUPPORTED: https://en.wikipedia.org/wiki/Cranmore_Castle]; Cranmore Castle may have been a winter enclosure for livestock [SUPPORTED: https://en.wikipedia.org/wiki/Cranmore_Castle]; Cranmore Castle may have been a market site [SUPPORTED: https://en.wikipedia.org/wiki/Cranmore_Castle]; Cranmore Castle could point to a tribal oppidum [SUPPORTED: https://en.wikipedia.org/wiki/Cranmore_Castle]; The River Exe and the River Lowman meet (Tiverton stands at their confluence) [SUPPORTED: https://en.wikipedia.org/wiki/Tiverton,_Devon]; Stone Age flint tools have been found in the Tiverton area [SUPPORTED: https://en.wikipedia.org/wiki/Tiverton,_Devon]; Tiverton''s name is conjectured to derive from words meaning \"the town on two fords\" [SUPPORTED: https://en.wikipedia.org/wiki/Tiverton,_Devon]"}]'::jsonb),
    ('010c0b09-760b-44f6-ba68-1f0353c7b3e6'::uuid, 'card_description', 'An earthquake in 1821 revealed the Cave of Ardales in Malaga province, where over 1,000 paintings and engravings lie across the walls, the ceilings and the speleothems.', NULL, 'teaser-card-s032-rollback:010c0b09-760b-44f6-ba68-1f0353c7b3e6:card_description', 'rollback of teaser-card-s032: card_description None restored on Cave of Ardales', '4e5b9b2fcd5d9db759afb136d47e38140551ab9159a7aeaf7f7d8ffe84a28dd7|7c728a35a6e1492b40a2e264b84cb9d8263cde54a9675df52fa3b85d3b23b138|7c728a35a6e1492b40a2e264b84cb9d8263cde54a9675df52fa3b85d3b23b138', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "An earthquake in 1821 revealed the Cave of Ardales in Malaga province, where over 1,000 paintings and engravings lie across the walls, the ceilings and the speleothems."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "an earthquake in 1821 revealed the Cave of Ardales [S1]; the cave is in Malaga province [S1]; the cave contains over 1,000 paintings and engravings [S2]; the paintings and engravings lie on walls, ceilings and speleothems [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Cave of Ardales is a prehistoric rock-art cave (arte parietal) in southern Spain. [SUPPORTED: https://es.wikipedia.org/wiki/Cueva_de_Ardales]; The cave lies in the municipality of Ardales, Málaga province, Andalusia. [SUPPORTED: https://es.wikipedia.org/wiki/Cueva_de_Ardales]; An earthquake in 1821 revealed the cave and freed its entrance. [SUPPORTED: https://es.wikipedia.org/wiki/Cueva_de_Ardales]; The cave holds over 1,000 painted and engraved motifs. [SUPPORTED: https://es.wikipedia.org/wiki/Cueva_de_Ardales]; The paintings and engravings lie across the walls, the ceilings and the speleothems of the cave. [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('018c0c9d-c85f-4ed9-86eb-8cf350ec83e7'::uuid, 'card_description', 'In Chinchaypujio District of Cusco, Pumawasi is a pre-Columbian rock art cave 22 m deep, 30 m wide and 19 m high. Ceramics and human bone remains show burial ground and ceremonial use.', NULL, 'teaser-card-s032-rollback:018c0c9d-c85f-4ed9-86eb-8cf350ec83e7:card_description', 'rollback of teaser-card-s032: card_description None restored on Pumawasi, Anta', 'b3f263f1985edc5ee3e00e140902ffbde5132cb0133f2f17f14638eba0580f49|a70e1c51272ad3533762dbc1a79140cb40b2ed725b4754f8281ce9e1d5f2d010|a70e1c51272ad3533762dbc1a79140cb40b2ed725b4754f8281ce9e1d5f2d010', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "In Chinchaypujio District of Cusco, Pumawasi is a pre-Columbian rock art cave 22 m deep, 30 m wide and 19 m high. Ceramics and human bone remains show burial ground and ceremonial use."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Pumawasi is in Chinchaypujio District of Cusco [S1]; Pumawasi is a pre-Columbian rock art cave [S1]; the cave measures 22 m deep [S1]; the cave measures 30 m wide [S1]; the cave measures 19 m high [S1]; ceramics and human bone remains were recovered [S2]; they indicate use as a burial ground [S2]; they indicate use as a ceremonial site [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Pumawasi is a cave with pre-Columbian rock art in Peru. [SUPPORTED: https://en.wikipedia.org/wiki/Pumawasi,_Anta]; It lies in Chinchaypujio District, Anta Province, Cusco region, Peru. [SUPPORTED: https://en.wikipedia.org/wiki/Pumawasi,_Anta]; The cave is about 22 metres deep. [SUPPORTED: https://en.wikipedia.org/wiki/Pumawasi,_Anta]; The cave measures about 30 metres at its widest point. [SUPPORTED: https://en.wikipedia.org/wiki/Pumawasi,_Anta]; The cave is about 19 metres high. [SUPPORTED: http://www.rupestreweb.info/pinturaspumawasi.html]; Ceramics, fragments of red and black pottery, were found in the cave. [SUPPORTED: http://www.rupestreweb.info/pinturaspumawasi.html]; Human bone remains were found in the cave. [SUPPORTED: http://www.rupestreweb.info/pinturaspumawasi.html]; The cave was used as a burial ground. [SUPPORTED: https://en.wikipedia.org/wiki/Pumawasi,_Anta]; The cave was also used for ceremonies and rites associated with the dead. [SUPPORTED: http://www.rupestreweb.info/pinturaspumawasi.html]"}]'::jsonb),
    ('01914c11-fb33-4778-a0ef-fd616ff33b88'::uuid, 'card_description', 'Cumae, the first Greek colony on mainland Italy, was founded around 725 BC from Chalcis. Famed as the home of the Cumaean Sibyl, it holds a purported 130-metre underground corridor.', NULL, 'teaser-card-s032-rollback:01914c11-fb33-4778-a0ef-fd616ff33b88:card_description', 'rollback of teaser-card-s032: card_description None restored on Cumae', 'e8876256b564865f6fc98a3448ce52f86d59d152d26bc4a7b0cd14e3b69f09cf|ac17d4d73741d5cc0b56ed03708e78afdde1c26ef917b7441070550c0aec5200|ac17d4d73741d5cc0b56ed03708e78afdde1c26ef917b7441070550c0aec5200', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Cumae, the first Greek colony on mainland Italy, was founded around 725 BC from Chalcis. Famed as the home of the Cumaean Sibyl, it holds a purported 130-metre underground corridor."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Cumae was the first ancient Greek colony on mainland Italy [S1]; it was founded around 725 BC [S1]; it was founded by settlers from Chalcis [S1]; the site is famed as the home of the Cumaean Sibyl [S3]; the site holds a purported 130-metre underground corridor [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Cumae is an ancient Greek colony on mainland Italy whose remains lie in and around modern Cuma in Campania, west of Naples. [SUPPORTED: https://en.wikipedia.org/wiki/Cumae]; Cumae was the first Greek colony on mainland Italy. [SUPPORTED: https://en.wikipedia.org/wiki/Cumae]; Cumae was founded around 725 BC. [SUPPORTED: https://www.ancientworldmagazine.com/articles/home-sibyl-greek-colony-cumae/]; The founders of Cumae came from Chalcis. [SUPPORTED: https://www.ancientworldmagazine.com/articles/home-sibyl-greek-colony-cumae/]; Cumae is famous as the home / seat of the Cumaean Sibyl. [SUPPORTED: https://en.wikipedia.org/wiki/Cumae]; Cumae holds a purported 130-metre underground corridor. [SUPPORTED: https://www.ancientworldmagazine.com/articles/home-sibyl-greek-colony-cumae/]"}]'::jsonb),
    ('01b50bc7-3e36-494e-9a91-fc4d60323ada'::uuid, 'card_description', 'Franchthi Cave overlooks Kiladha Bay, where finds trace the transition from Paleolithic hunter-gatherers to Neolithic farmers, with domesticated plants and animals appearing around 7,000 BC.', NULL, 'teaser-card-s032-rollback:01b50bc7-3e36-494e-9a91-fc4d60323ada:card_description', 'rollback of teaser-card-s032: card_description None restored on Franchthi Cave', 'ec79b2ad6280c729e691e18085c95a418b8881ded53bb21e06729321dfe00a45|1db243cc9f98c16a26c765b1c5c6e6f7897eeefcec6aec189128482e8fe5f7fc|1db243cc9f98c16a26c765b1c5c6e6f7897eeefcec6aec189128482e8fe5f7fc', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Franchthi Cave overlooks Kiladha Bay, where finds trace the transition from Paleolithic hunter-gatherers to Neolithic farmers, with domesticated plants and animals appearing around 7,000 BC."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Franchthi Cave overlooks Kiladha Bay [S1]; the site''s finds trace the transition from Paleolithic hunter-gatherers to Neolithic farmers [S2]; domesticated plants and animals appear around 7,000 BC [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Franchthi Cave is an archaeological site overlooking Kiladha Bay in the Argolic Gulf, opposite the village of Kiladha in southeastern Argolis, Greece. [SUPPORTED: https://en.wikipedia.org/wiki/Franchthi_Cave]; The finds at Franchthi Cave trace occupation from the Paleolithic through the Mesolithic to the Neolithic, i.e. the transition from hunter-gatherers to farmers. [SUPPORTED: https://en.wikipedia.org/wiki/Franchthi_Cave]; The Mesolithic hunter-gatherers of Franchthi adopted Neolithic farming methods. [SUPPORTED: https://en.wikipedia.org/wiki/Franchthi_Cave]; The cave contains some of the earliest evidence for agriculture in Greece. [SUPPORTED: https://en.wikipedia.org/wiki/Franchthi_Cave]; The remains of domesticated plants and animals appear in the cave around 7,000 BC. [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Franchthi_Cave]"}]'::jsonb),
    ('01cdc8e2-56b7-4c9d-b6d0-68c290a65e55'::uuid, 'card_description', 'Near Sartène in the Sartenais region of southern Corsica, Apazzu is a prehistoric megalithic site. Excavations uncovered artifacts, among them a stone vase with a zoomorphic protome.', NULL, 'teaser-card-s032-rollback:01cdc8e2-56b7-4c9d-b6d0-68c290a65e55:card_description', 'rollback of teaser-card-s032: card_description None restored on Apazzu', '841d784af51d12923cf40aaa973d015fb12c24311d18ed6f2edecf1d8d783c6c|9fb58c1017e0dd5782bc671a297e61e5b09bff9a9a6f9a54b21036de57efa7f1|9fb58c1017e0dd5782bc671a297e61e5b09bff9a9a6f9a54b21036de57efa7f1', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Near Sartène in the Sartenais region of southern Corsica, Apazzu is a prehistoric megalithic site. Excavations uncovered artifacts, among them a stone vase with a zoomorphic protome."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Apazzu is in the Sartenais region of southern Corsica [S1]; Apazzu is near Sartene [S1]; Apazzu is a prehistoric megalithic site [S1]; excavations uncovered artifacts [S2]; among them a stone vase with a zoomorphic protome [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Apazzu is a prehistoric megalithic site (a megalithic alignment with a tumulus) [SUPPORTED: https://fr.wikipedia.org/wiki/Menhirs_d%27Apazzu]; Apazzu lies in the commune of Sartène [SUPPORTED: https://fr.wikipedia.org/wiki/Menhirs_d%27Apazzu]; Sartène, the commune the site belongs to, is the capital of the Sartenais [SUPPORTED: https://fr.wikipedia.org/wiki/Sart%C3%A8ne]; Corse-du-Sud, the department named for the site''s location, consists of the southern part of the island of Corsica [SUPPORTED: https://en.wikipedia.org/wiki/Corse-du-Sud]; Archaeological interventions (excavations) took place at Apazzu [SUPPORTED: https://fr.wikipedia.org/wiki/Menhirs_d%27Apazzu]; Objects were found at Apazzu, among them a stone vase [SUPPORTED: https://fr.wikipedia.org/wiki/Menhirs_d%27Apazzu]; The stone vase from Apazzu carries a zoomorphic protome [SUPPORTED: https://fr.wikipedia.org/wiki/Menhirs_d%27Apazzu]"}]'::jsonb),
    ('01f3d961-e2cf-4a3d-bc36-7e9976efe93e'::uuid, 'card_description', '54 km southeast of Puno in the Titicaca Basin, Jisk''a Iru Muqu was occupied from circa 3400-1600 BCE. Excavations recovered obsidian tools, a gold necklace and early domestic architecture.', NULL, 'teaser-card-s032-rollback:01f3d961-e2cf-4a3d-bc36-7e9976efe93e:card_description', 'rollback of teaser-card-s032: card_description None restored on Jisk''a Iru Muqu', '12268d68370547296e445d9038977be9ae9158fc19f6779bf672a9669df9b14f|c27be8decdb3a8a45986cb35874101cd73e8c58d8a3a10558ffcd04dcf9e613a|c27be8decdb3a8a45986cb35874101cd73e8c58d8a3a10558ffcd04dcf9e613a', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "54 km southeast of Puno in the Titicaca Basin, Jisk''a Iru Muqu was occupied from circa 3400-1600 BCE. Excavations recovered obsidian tools, a gold necklace and early domestic architecture."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Jisk''a Iru Muqu is 54 km southeast of Puno [S1]; it is in the Lake Titicaca Basin [S1]; it was occupied from circa 3400-1600 BCE [S2]; excavations recovered obsidian tools [S3]; excavations recovered a gold necklace [S3]; excavations recovered early domestic architecture [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Jisk''a Iru Muqu is a pre-Columbian archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Jisk%27a_Iru_Muqu]; The site lies 54 km south-east of Puno [SUPPORTED: https://en.wikipedia.org/wiki/Jisk%27a_Iru_Muqu]; The site lies in the Lake Titicaca Basin [SUPPORTED: https://pmc.ncbi.nlm.nih.gov/articles/PMC5137686/]; The site was occupied from circa 3400 to 1600