    ('0286a741-77f2-4148-8e62-487041920281'::uuid, 'card_description', 'In the district of Huayopata, La Convención Province, in the Cusco region of Peru, an archaeological site carries two spellings: Cochapata, also written Qochapata.', NULL, 'teaser-card-s032-rollback:0286a741-77f2-4148-8e62-487041920281:card_description', 'rollback of teaser-card-s032: card_description None restored on Cochapata', 'e273ebf8c7ce0666f047d8cb170351d9300a671e433b66a0885cb770d1880606|ba3f07996ee8d349ef06abcf3f60383e490606481e075f7f262ffdc8252fc74e|ba3f07996ee8d349ef06abcf3f60383e490606481e075f7f262ffdc8252fc74e', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "In the district of Huayopata, La Convención Province, in the Cusco region of Peru, an archaeological site carries two spellings: Cochapata, also written Qochapata."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site is in the district of Huayopata, La Convencion Province, in the Cusco region of Peru [S1]; it is an archaeological site [S1]; its name is spelled Cochapata and also Qochapata [S1]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Cochapata is an archaeological site in Peru [SUPPORTED: https://es.wikipedia.org/wiki/Cochapata]; The site is in the district of Huayopata [SUPPORTED: https://es.wikipedia.org/wiki/Cochapata]; The site is in La Convencion Province [SUPPORTED: https://es.wikipedia.org/wiki/Cochapata]; The site is in the Cuzco (Cusco) department of Peru [SUPPORTED: https://es.wikipedia.org/wiki/Cochapata]; The site is spelled Cochapata and also Qochapata [SUPPORTED, no proving quote: https://es.wikipedia.org/wiki/Cochapata]"}]'::j