    ('036346d9-313c-4fcd-9649-1aaba368e72e'::uuid, 'card_description', NULL, '4th-century BC cistern cut into bedrock on the summit of Lycian Kyaneai. This water structure kept the mountain city viable across Hellenistic, Roman, and Byzantine occupation spanning centuries.', 'teaser-card-s032-rollback:036346d9-313c-4fcd-9649-1aaba368e72e:card_description', 'rollback of teaser-card-s032: card_description ''4th-century BC cistern cut into bedrock on the summit of Lycian Kyaneai. This water structure kept the mountain city viable across Hellenistic, Roman, and Byzantine occupation spanning centuries.'' restored on Kyaneai Tarihi Sarnıç', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('03a7a357-12a8-40f9-ae6a-9cef78135fd3'::uuid, 'card_description', 'Dubris, on the site of Dover, became the main Roman cross-Channel port, taking over from Rutupiae. A 1970s bypass uncovered its remains; an eight-week excavation found a Roman mansio.', NULL, 'teaser-card-s032-rollback:03a7a357-12a8-40f9-ae6a-9cef78135fd3:card_description', 'rollback of teaser-card-s032: card_description None restored on Dubris', 'ec3b741ad4cfbf817b1fbe73df3aaec2fe9828a083fb320e651efbea2fbd7f92|d2dc8b1e569dd57f4d582b0f8e881c5089ffa1b240bd2f65794dbb5d718037c1|d2dc8b1e569dd57f4d582b0f8e881c5089ffa1b240bd2f65794dbb5d718037c1', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Dubris, on the site of Dover, became the main Roman cross-Channel port, taking over from Rutupiae. A 1970s bypass uncovered its remains; an eight-week excavation found a Roman mansio."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Dubris is on the site of present-day Dover [S1]; it became the main Roman cross-Channel port [S4]; it took over that role from Rutupiae [S4]; a bypass built in the 1970s uncovered Roman remains of the site [S6]; an eight-week excavation followed [S6]; the excavation found a Roman mansio [S7]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Dubris was a port in Roman Britain [SUPPORTED: https://en.wikipedia.org/wiki/Dubris]; Dubris stands on the site of present-day Dover, Kent, England [SUPPORTED: https://en.wikipedia.org/wiki/Dubris]; At its peak Dubris was the main Roman cross-Channel port [SUPPORTED: https://en.wikipedia.org/wiki/Dubris]; Dubris took over from Rutupiae [SUPPORTED: https://en.wikipedia.org/wiki/Dubris]; Construction of the A256/York Street bypass in the 1970s uncovered Roman remains at the site [SUPPORTED: https://en.wikipedia.org/wiki/Dubris]; An eight-week excavation followed the discovery [SUPPORTED: https://en.wikipedia.org/wiki/Dubris]; The archaeologists found a Roman mansio [SUPPORTED: https://en.wikipedia.org/wiki/Dubris]"}]'::jsonb),
    ('04982451-5603-41cb-957d-758925170c8e'::uuid, 'card_description', 'M''Daourouch sits at the site of the ancient Berber-Roman town of Madauros in Numidia. Two names, one piece of ground: Madauros for the ancient town, M''Daourouch for the site standing there.', NULL, 'teaser-card-s032-rollback:04982451-5603-41cb-957d-758925170c8e:card_description', 'rollback of teaser-card-s032: card_description None restored on M''Daourouch', '4349224f639a71842775099f30eaeccea0f68e50126a20eaa910dc3fcd5ff3e0|b875256f2e5eaec54f9491fcb0a0d9c4c44c7346f6cf982956bf20637fe026e2|b875256f2e5eaec54f9491fcb0a0d9c4c44c7346f6cf982956bf20637fe026e2', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "M''Daourouch sits at the site of the ancient Berber-Roman town of Madauros in Numidia. Two names, one piece of ground: Madauros for the ancient town, M''Daourouch for the site standing there."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "M''Daourouch sits at the site of the ancient Berber-Roman town of Madauros [S1]; the ancient town is in Numidia [S1]; the present-day place and the ancient town stand on the same ground [S1]; Madauros names the ancient town [S1]; M''Daourouch names the site there [S1]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "M''Daourouch occupies the site of the ancient town of Madauros [SUPPORTED: https://en.wikipedia.org/wiki/M%27Daourouch]; M''Daourouch is a commune in Souk Ahras Province, Algeria [SUPPORTED: https://en.wikipedia.org/wiki/M%27Daourouch]; Madauros was a Berber-Roman town [SUPPORTED: https://en.wikipedia.org/wiki/M%27Daourouch]; Madauros lay in Numidia [SUPPORTED: https://en.wikipedia.org/wiki/M%27Daourouch]; Madauros and M''daourouch are names for the same piece of ground, the ancient site and its ruins [SUPPORTED: https://en.wikipedia.org/wiki/M%27Daourouch]"}]'::jsonb),
    ('057ed947-18f5-45f5-b4c6-6bc1e29264d7'::uuid, 'card_description', 'On a spur of Dinedor Hill, Dinedor Camp looks east to where the Wye meets the Lugg. In 1951 a trench was cut from the rampart edge about 35 metres towards the centre of the camp.', NULL, 'teaser-card-s032-rollback:057ed947-18f5-45f5-b4c6-6bc1e29264d7:card_description', 'rollback of teaser-card-s032: card_description None restored on Dinedor Camp', 'af163050dd20d19581055502b4a9ee2db7051f3ecb03d1e4c581af60de060a34|c11691d806bfc1a97a8dc882aa7c438bb89932ffa908d7d25c672b2a9479ac35|c11691d806bfc1a97a8dc882aa7c438bb89932ffa908d7d25c672b2a9479ac35', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On a spur of Dinedor Hill, Dinedor Camp looks east to where the Wye meets the Lugg. In 1951 a trench was cut from the rampart edge about 35 metres towards the centre of the camp."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the card''s subject is the site named Dinedor Camp [S1]; it stands on a spur of Dinedor Hill [S2]; from there it looks east to where the River Wye meets the River Lugg [S2]; in 1951 a trench was cut [S6]; the trench ran from the edge of the rampart about 35 metres towards the centre of the camp [S6]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Dinedor Camp is a fort, an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Dinedor_Camp]; The camp stands on a spur of Dinedor Hill [SUPPORTED: https://en.wikipedia.org/wiki/Dinedor_Camp]; From the camp one looks east to the point where the River Wye meets the River Lugg [SUPPORTED: https://en.wikipedia.org/wiki/Dinedor_Camp]; A trench was dug in 1951 at the north-east of the fort [SUPPORTED: https://en.wikipedia.org/wiki/Dinedor_Camp]; The 1951 trench was cut from the edge of the rampart [SUPPORTED: https://en.wikipedia.org/wiki/Dinedor_Camp]; The 1951 trench was about 35 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Dinedor_Camp]; The 1951 trench ran towards the centre of the camp [SUPPORTED: https://en.wikipedia.org/wiki/Dinedor_Camp]"}]'::jsonb),
    ('05afa876-bd9b-4285-8aa3-cb1f71fb3707'::uuid, 'card_description', 'About 200 meters north of the Araz River, Ərəbyengicə is an ancient settlement whose finds include obsidian remains and combed-surface pottery of the Late Chalcolithic.', NULL, 'teaser-card-s032-rollback:05afa876-bd9b-4285-8aa3-cb1f71fb3707:card_description', 'rollback of teaser-card-s032: card_description None restored on Ərəbyengicə', 'a9eb52141a627ba28a56a4da51f5819b246b67044c6fbee2915c12f08003acc3|135cf7e5bf489d980eff31772a04bb146e0eda4754f3c25f1cec83eed1973936|135cf7e5bf489d980eff31772a04bb146e0eda4754f3c25f1cec83eed1973936', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "About 200 meters north of the Araz River, Ərəbyengicə is an ancient settlement whose finds include obsidian remains and combed-surface pottery of the Late Chalcolithic."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the settlement lies about 200 meters north of the Araz River [S1]; it is an ancient settlement [S1]; its finds include obsidian remains [S3]; its finds include combed-surface ceramics typical of the Late Chalcolithic [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Ərəbyengicə is an ancient settlement (in the Sharur region of Azerbaijan) [SUPPORTED: https://en.wikipedia.org/wiki/%C6%8Fr%C9%99byengic%C9%99]; The settlement lies about 200 metres north of the Araz River [SUPPORTED: https://en.wikipedia.org/wiki/%C6%8Fr%C9%99byengic%C9%99]; The settlement lies south of the village of Ərəbyengicə (Erebyengicesi) [SUPPORTED: https://en.wikipedia.org/wiki/%C6%8Fr%C9%99byengic%C9%99]; Remains of obsidian have been found at the settlement [SUPPORTED: https://en.wikipedia.org/wiki/%C6%8Fr%C9%99byengic%C9%99]; Chaff-faced and chaff-tempered ware has been found at the site, sometimes with combed surfaces [SUPPORTED: https://en.wikipedia.org/wiki/%C6%8Fr%C9%99byengic%C9%99]; Combed-surface chaff-faced pottery is typical of the Late Chalcolithic of southern Azerbaijan [SUPPORTED: https://en.wikipedia.org/wiki/%C6%8Fr%C9%99byengic%C9%99]"}]'::jsonb),
    ('05f23376-78dc-4cb6-941d-faaea3abe6aa'::uuid, 'card_description', 'Tindari''s Greek theater, built between the 4th and 3rd centuries BC, could seat 3,000 spectators. In the 1st century AD part of the cliff collapsed; earthquakes did more in the 4th century.', NULL, 'teaser-card-s032-rollback:05f23376-78dc-4cb6-941d-faaea3abe6aa:card_description', 'rollback of teaser-card-s032: card_description None restored on Tindari', '41d39adc7c5dbc28467725cfda7f1247fb062a3e56bd24ac9fc5c609c2e71119|b8ad9e0d9e7e1b9975fdaa2ac88e61ac968d16377ec5ff82eb089c255fe8cf58|b8ad9e0d9e7e1b9975fdaa2ac88e61ac968d16377ec5ff82eb089c255fe8cf58', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Tindari''s Greek theater, built between the 4th and 3rd centuries BC, could seat 3,000 spectators. In the 1st century AD part of the cliff collapsed; earthquakes did more in the 4th century."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Tindari has a Greek theater [S1]; the theater was built between the 4th and 3rd centuries BC [S1]; the theater could seat 3,000 spectators [S1]; part of the cliff collapsed in the 1st century AD [S2]; earthquakes caused further damage in the 4th century [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Tindari is an ancient city of Greek origin in Sicily, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Tindari]; Tindari has a theatre built in Greek forms [SUPPORTED: https://it.wikipedia.org/wiki/Teatro_greco_di_Tindari]; The theatre was built in the 4th-3rd century BC period (the page dates its Greek construction to the end of the 4th century BC, later remodelled in Roman times) [SUPPORTED: https://it.wikipedia.org/wiki/Teatro_greco_di_Tindari]; The theatre could seat about 3,000 spectators [SUPPORTED: https://it.wikipedia.org/wiki/Teatro_greco_di_Tindari]; In the 1st century AD (AD 17) Tindari was struck by a great landslide [SUPPORTED: https://it.wikipedia.org/wiki/Tindari]; Part of the cliff fell in at Tindari (the page states it is not improbable that part of the cliff fell in, as recorded by Pliny) [SUPPORTED: https://en.wikipedia.org/wiki/Tindari]; Tindari was hit by destructive earthquakes in the 4th century, more than the AD 17 landslide [SUPPORTED: https://it.wikipedia.org/wiki/Tindari]"}]'::jsonb),
    ('06a44374-50d9-4bc1-b747-41fa09e28eee'::uuid, 'card_description', 'Near the village of Ninamaca, about 30 chullpas of pre-Inca times stand on top of a mountain at about 3,000 m. Ninamarca is possibly Quechua nina, fire, and marka, village: fire village.', NULL, 'teaser-card-s032-rollback:06a44374-50d9-4bc1-b747-41fa09e28eee:card_description', 'rollback of teaser-card-s032: card_description None restored on Ninamarca', '9f86c5f2ef94fa5c6896dffd569afe664bc9bf74530b04e999c0417a20c5b3d0|e4830f5c5c4a3c8a747fec5a44aec0542f2d6ae5195d3b952b04c1f42c1dc062|e4830f5c5c4a3c8a747fec5a44aec0542f2d6ae5195d3b952b04c1f42c1dc062', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Near the village of Ninamaca, about 30 chullpas of pre-Inca times stand on top of a mountain at about 3,000 m. Ninamarca is possibly Quechua nina, fire, and marka, village: fire village."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "about 30 chullpas of pre-Inca times stand there [S3]; the chullpas stand on top of a mountain at about 3,000 m [S3]; the site is near the village of Ninamaca [S2]; the name Ninamarca is possibly from the Quechua nina ''fire'' and marka ''village'', ''fire village'' [S1]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Ninamarca is an archaeological site in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Ninamarca]; Ninamarca lies in the Cusco Region, Paucartambo Province, Colquepata District [SUPPORTED: https://en.wikipedia.org/wiki/Ninamarca]; Ninamarca is southeast of Colquepata, near the village of Ninamaca [SUPPORTED: https://en.wikipedia.org/wiki/Ninamarca]; There are about 30 chullpas at Ninamarca [SUPPORTED: https://en.wikipedia.org/wiki/Ninamarca]; The chullpas are of pre-Inca times [SUPPORTED: https://en.wikipedia.org/wiki/Ninamarca]; The chullpas stand on top of a mountain at about 3,000 m [SUPPORTED: https://en.wikipedia.org/wiki/Ninamarca]; The name Ninamarca possibly comes from Quechua nina (fire) and marka (village), ''fire village'' [SUPPORTED: https://en.wikipedia.org/wiki/Ninamarca]"}]'::jsonb),
    ('07947420-54ee-4cf5-ac06-47814ce7f56d'::uuid, 'card_description', 'Digging for a ferret in 1864, a gamekeeper uncovered Chedworth Roman Villa, one of the largest Roman villas found in Britain. Its west wing held a mosaic dining-room and two bathing suites.', NULL, 'teaser-card-s032-rollback:07947420-54ee-4cf5-ac06-47814ce7f56d:card_description', 'rollback of teaser-card-s032: card_description None restored on Chedworth Roman Villa', '9d3aa580cb5e21b947f5bcb20ecba8976725fdb42200a5dd6974608148b8a7e0|e614182c03b2b04143807fc6b4bd3221add4f8916c705a6293a04347d698f6db|e614182c03b2b04143807fc6b4bd3221add4f8916c705a6293a04347d698f6db', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Digging for a ferret in 1864, a gamekeeper uncovered Chedworth Roman Villa, one of the largest Roman villas found in Britain. Its west wing held a mosaic dining-room and two bathing suites."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "a gamekeeper digging for a ferret uncovered the villa in 1864 [S5]; it is one of the largest Roman villas discovered in Britain [S2]; the west wing contained a dining-room with a mosaic floor [S4]; the building contained two separate bathing suites [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Chedworth is a Roman villa near Chedworth, Gloucestershire, England [SUPPORTED: https://en.wikipedia.org/wiki/Chedworth_Roman_Villa]; Chedworth Roman Villa is one of the largest Roman villas found in Britain [SUPPORTED: https://en.wikipedia.org/wiki/Chedworth_Roman_Villa]; The villa was uncovered in 1864 by a gamekeeper who was digging for a ferret [SUPPORTED: https://en.wikipedia.org/wiki/Chedworth_Roman_Villa]; The west wing contained a dining-room (triclinium) with a mosaic floor [SUPPORTED: https://en.wikipedia.org/wiki/Chedworth_Roman_Villa]; There were two separate bathing suites, one for damp-heat and one for dry-heat [SUPPORTED: https://en.wikipedia.org/wiki/Chedworth_Roman_Villa]"}]'::jsonb),
    ('08861937-eb56-4be0-9fef-778754fcfc1d'::uuid, 'card_description', 'At Hartashen Megalithic Avenue, two avenues of basalt menhirs stand at an angle in three rows each, and the lines never meet. What the rows were for is unclear; the site has no firm dating.', NULL, 'teaser-card-s032-rollback:08861937-eb56-4be0-9fef-778754fcfc1d:card_description', 'rollback of teaser-card-s032: card_description None restored on Hartashen Megalithic Avenue', '5698b633b32e435beb8bb755e083bf94cad31636dcff819a2718ec90a5c6ac4c|8d8a16968d933855240cf5cc8a35db3747ec3ba27ef03348157657d6421af5da|8d8a16968d933855240cf5cc8a35db3747ec3ba27ef03348157657d6421af5da', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "At Hartashen Megalithic Avenue, two avenues of basalt menhirs stand at an angle in three rows each, and the lines never meet. What the rows were for is unclear; the site has no firm dating."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site consists of two avenues of megalithic rocks [S1]; the avenues are built of basalt stones placed at an angle [S2]; menhirs are arranged in three rows in each avenue [S2]; the two avenues do not intersect [S1]; the purpose of the three rows of menhirs is unclear [S3]; the site has no firm dating [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Hartashen Megalithic Avenue is a megalithic monument of standing stones in Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Hartashen_Megalithic_Avenue]; The site consists of two avenues of megalithic rocks [SUPPORTED: https://en.wikipedia.org/wiki/Hartashen_Megalithic_Avenue]; The two avenues/lines never meet (do not intersect) [SUPPORTED: https://en.wikipedia.org/wiki/Hartashen_Megalithic_Avenue]; The menhirs are made of basalt [SUPPORTED: https://en.wikipedia.org/wiki/Hartashen_Megalithic_Avenue]; The stones stand at an angle [SUPPORTED: https://en.wikipedia.org/wiki/Hartashen_Megalithic_Avenue]; The menhirs are arranged in three rows in each avenue [SUPPORTED: https://en.wikipedia.org/wiki/Hartashen_Megalithic_Avenue]; The purpose of the three rows of menhirs is unclear and still under research [SUPPORTED: https://en.wikipedia.org/wiki/Hartashen_Megalithic_Avenue]; The site has no firm dating [SUPPORTED: https://en.wikipedia.org/wiki/Hartashen_Megalithic_Avenue]"}]'::jsonb),
    ('0b54890b-b30b-4836-9c8c-805cf88a4a21'::uuid, 'card_description', 'At the foot of the mountain Qayakuna, in the village of Quchaq north of the town Cerro de Pasco, Qaqapatan keeps its rock paintings high at approximately 3,782 metres.', NULL, 'teaser-card-s032-rollback:0b54890b-b30b-4836-9c8c-805cf88a4a21:card_description', 'rollback of teaser-card-s032: card_description None restored on Qaqapatan', 'fdfbe3a712093490a65d83b4f44fb99ed8af57de6b97ac136b885d87c4aca99c|fc8dd108286d7a6ce769ba7ce07c3b21fee134120b68ae2404e63d5b8f55577f|fc8dd108286d7a6ce769ba7ce07c3b21fee134120b68ae2404e63d5b8f55577f', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "At the foot of the mountain Qayakuna, in the village of Quchaq north of the town Cerro de Pasco, Qaqapatan keeps its rock paintings high at approximately 3,782 metres."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Qaqapatan is an archaeological site with rock paintings [S1]; the site is at the foot of the mountain Qayakuna [S2]; the site is in the village of Quchaq, north of the town Cerro de Pasco [S2]; the site lies at an elevation of approximately 3,782 metres [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Qaqapatan is an archaeological site with rock paintings in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Qaqapatan]; The rock paintings are at a height of about 3,782 metres [SUPPORTED: https://en.wikipedia.org/wiki/Qaqapatan]; The site lies at the foot of the mountain Qayakuna [SUPPORTED: https://en.wikipedia.org/wiki/Qaqapatan]; The site lies in the village of Quchaq (Cochac) [SUPPORTED: https://en.wikipedia.org/wiki/Qaqapatan]; Quc