    ('0bf5e631-0ee8-4b75-9c06-fd6d713cc42d'::uuid, 'card_description', 'Deriivka, a Copper Age site on the Dnieper, gave up a horse burial with apparent bit wear, first read as the earliest evidence of riding. Radiocarbon dating put the skull in the Iron Age.', NULL, 'teaser-card-s032-rollback:0bf5e631-0ee8-4b75-9c06-fd6d713cc42d:card_description', 'rollback of teaser-card-s032: card_description None restored on Deriivka', '48f5050248a5682599e7233dc7d410364fc396405e9a41879efaf236dd29d94e|9bd8a3e287f775f5cf155462dff1b226893dced36572a717c8cddc0b9da3d7a5|9bd8a3e287f775f5cf155462dff1b226893dced36572a717c8cddc0b9da3d7a5', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Deriivka, a Copper Age site on the Dnieper, gave up a horse burial with apparent bit wear, first read as the earliest evidence of riding. Radiocarbon dating put the skull in the Iron Age."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Deriivka is a Copper Age site [S1]; it lies on the Dnieper [S1]; the site yielded a horse burial with apparent bit wear [S2]; the burial was initially interpreted as the earliest evidence of horse domestication and riding [S2]; radiocarbon dating later dated the horse skull to the Iron Age [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Deriivka is an archaeological site in Ukraine [SUPPORTED: https://en.wikipedia.org/wiki/Deriivka]; Deriivka is a Copper Age site (Sredny Stog culture) [SUPPORTED: https://en.wikipedia.org/wiki/Deriivka]; Deriivka lies on the Dnieper [SUPPORTED: https://en.wikipedia.org/wiki/Deriivka]; Deriivka gave up a horse burial with bit wear [SUPPORTED: https://en.wikipedia.org/wiki/Deriivka]; The horse burial was first read as the earliest evidence of horseback riding [SUPPORTED: https://en.wikipedia.org/wiki/Deriivka]; Radiocarbon dates showed the horse burial was intrusive, the horse having died circa 700-200 BC [SUPPORTED: https://en.wikipedia.org/wiki/Deriivka]; Radiocarbon dating placed the Deriivka horse in the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Domestication_of_the_horse]; The radiocarbon date was taken from the horse''s skull [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('0cf46f86-7eea-46ec-bf6c-b803d3145000'::uuid, 'card_description', 'Four faces, four passages: the Arch of Janus is the only surviving quadrifrons arch in Rome, 16 m high in the Forum Boarium. Built from older spolia, it may honor Constantine I.', NULL, 'teaser-card-s032-rollback:0cf46f86-7eea-46ec-bf6c-b803d3145000:card_description', 'rollback of teaser-card-s032: card_description None restored on Arch of Janus', 'f354453595f39836fc1e5ebf7dcda37d7d36a8a89740e0107c4a577da69ecc81|03a954825bf53398e84ada6ceee6c9c0e8e2ae1a748dfc3445079badd40c7b4d|03a954825bf53398e84ada6ceee6c9c0e8e2ae1a748dfc3445079badd40c7b4d', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Four faces, four passages: the Arch of Janus is the only surviving quadrifrons arch in Rome, 16 m high in the Forum Boarium. Built from older spolia, it may honor Constantine I."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the arch is a quadrifrons, that is four-faced [S1]; the arch has four passageways [S3]; it is the only surviving quadrifrons arch in Rome [S1]; it stands 16 m high [S1]; it stands in the Forum Boarium [S1]; it was built using spolia from earlier buildings [S2]; it may honor Constantine I [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Arch of Janus is a quadrifrons triumphal arch in Rome [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Janus]; The arch has four faces and four passages (four-fronted, four-arched) [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Janus]; It is the only surviving quadrifrons arch in Rome [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Janus]; The arch is 16 m high [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Janus]; The arch stands in the Forum Boarium [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Janus]; The arch was built from older spolia, material from earlier buildings [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Janus]; The arch may honour Constantine I [SUPPORTED: https://en.wikipedia.org/wiki/Arch_of_Janus]"}]'::jsonb),
