    ('0f7c84f4-7364-434d-b003-706c8d7a3275'::uuid, 'card_description', 'Cattle, deer, pig and goat bones lay beside the ceramics at Alampra, a Middle Bronze Age settlement of circa 1900-1650 BC in Cyprus, dug by John E. Coleman between 1974 and 1985.', NULL, 'teaser-card-s032-rollback:0f7c84f4-7364-434d-b003-706c8d7a3275:card_description', 'rollback of teaser-card-s032: card_description None restored on Alampra', '1fe84305e18b049927468a6cd515e8696bef2130b2f750b418910c803103c848|ca2e091135a88c0cb26d90267513065f01dfa83e424305010553c507502ea872|ca2e091135a88c0cb26d90267513065f01dfa83e424305010553c507502ea872', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-002", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Cattle, deer, pig and goat bones lay beside the ceramics at Alampra, a Middle Bronze Age settlement of circa 1900-1650 BC in Cyprus, dug by John E. Coleman between 1974 and 1985."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "finds include cattle, deer, pig and goat bones [S2]; finds include ceramics [S2]; the bones were found alongside the ceramics [S2]; Alampra is a Middle Bronze Age settlement of circa 1900-1650 BC [S1]; the site is in Cyprus [S1]; the site was excavated under John E. Coleman between 1974 and 1985 [S1]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Alampra is the site of a Middle Bronze Age settlement in Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Alampra]; Alampra is in the Nicosia District of Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Alampra]; The settlement dates to circa 1900-1650 BC [SUPPORTED: https://en.wikipedia.org/wiki/Alampra]; Cattle bones were found at Alampra [SUPPORTED: https://en.wikipedia.