    ('1803a375-2b6b-4335-b158-98a371ce8889'::uuid, 'card_description', 'On western Dartmoor, Merrivale holds double stone rows, the longest 263 metres, a circle of 11 granite stones about 18 metres across, and a standing menhir over 3 metres tall.', NULL, 'teaser-card-s032-rollback:1803a375-2b6b-4335-b158-98a371ce8889:card_description', 'rollback of teaser-card-s032: card_description None restored on Merrivale, Devon', 'f49da60f488b04471e624072720b351bcaaa2b10de4612e2c21c8226e535a6bb|e8dd56aefbe58c85f4cd9a9f954d48def1d173cdce800f2f4e9f1d150680836f|e8dd56aefbe58c85f4cd9a9f954d48def1d173cdce800f2f4e9f1d150680836f', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-003", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On western Dartmoor, Merrivale holds double stone rows, the longest 263 metres, a circle of 11 granite stones about 18 metres across, and a standing menhir over 3 metres tall."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site is on western Dartmoor [S1]; it has double stone rows [S2]; the longest stretches 263 metres [S2]; it has a stone circle of 11 granite stones about 18 metres in diameter [S2]; it has a standing menhir over 3 metres tall [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Merrivale is a group of prehistoric megalithic monuments: stone rows, a stone circle and standing stones. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/]; Merrivale is on western Dartmoor. [SUPPORTED: https://en.wikipedia.org/wiki/Merrivale,_Devon]; Merrivale has double stone rows. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/]; The longest stone row is 263 metres long. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/]; There is a circle of 11 granite stones. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/]; The stone circle is about 18 metres across. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/]; There is a standing menhir at Merrivale. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/]; The standing menhir is over 3 metres tall. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/merrivale-prehistoric-settlement/history/]"}]'::jsonb),
    ('184dfea2-b710-4c3a-a3e8-d8cea0738290'::uuid, 'card_description', 'On top of the mountain Allqu Willka in Ayacucho, Inka Raqay is an Inca site, and raqay in Quechua means a ruin, a shed, a storehouse, or a dormitory for farm laborers.', NULL, 'teaser-card-s032-rollback:184dfea2-b710-4c3a-a3e8-d8cea0738290:card_description', 'rollback of teaser-card-s032: card_description None restored on Inka Raqay, Ayacucho', 'f4105f3b1e60fc27267be3104c1324bf8a75023c022e852203a8d2f3c6326586|c605305505a5ed1cec9975ef4d7b7a6576b32e1f844ade6e307670ddf7c6c2b9|c605305505a5ed1cec9975ef4d7b7a6576b32e1f844ade6e307670ddf7c6c2b9', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-003", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On top of the mountain Allqu Willka in Ayacucho, Inka Raqay is an Inca site, and raqay in Quechua means a ruin, a shed, a storehouse, or a dormitory for farm laborers."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site sits on top of the mountain Allqu Willka [S1]; it is in Ayacucho [S1]; Inka Raqay is an Inca archaeological site [S1]; raqay means a ruin, shed, storehouse or dormitory for farm laborers in Quechua [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Inka Raqay in the Ayacucho Region of Peru is an Inca archaeological site [SUPPORTED: https://es.wikipedia.org/wiki/Incarracay_(Ayacucho)]; The site stands on top of the mountain called Allqu Willka [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Ayacucho]; The site lies in the Ayacucho Region of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Ayacucho]; In Quechua, raqay means a ruin or demolished building, and also a shed, a storehouse or a dormitory for the labourers of a farm [SUPPORTED: https://en.wikipedia.org/wiki/Inka_Raqay,_Ayacucho]"}]'::jsonb),
    ('18911cb2-dff1-4d14-9110-de55c40706c0'::uuid, 'card_description', 'Goldsborough keeps a square Roman signal mound, roughly 30 m across and 1.4 m high. Excavations in 1918 found two skeletons and a large dog inside, jaws at one man''s throat.', NULL, 'teaser-card-s032-rollback:18911cb2-dff1-4d14-9110-de55c40706c0:card_description', 'rollback of teaser-card-s032: card_description None restored on Goldsborough, Scarborough', 'fecec56658a1b8383651c4acb30629ee87ba8714130bc5747355a52043435566|9c6962d7e28d7e4eb753a64e4afde1a6e726d9e02872de15923fb7c2e67205ac|9c6962d7e28d7e4eb753a64e4afde1a6e726d9e02872de15923fb7c2e67205ac', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-003", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Goldsborough keeps a square Roman signal mound, roughly 30 m across and 1.4 m high. Excavations in 1918 found two skeletons and a large dog inside, jaws at one man''s throat."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Goldsborough preserves a square Roman signal station mound [S1, S2]; the mound is roughly 30 m across [S2]; the mound is 1.4 m high [S2]; excavations took place in 1918 [S3]; two skeletons and a large dog were found inside the mound [S3]; the dog''s jaws were at one man''s throat [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Goldsborough is the site of a Roman signal station [SUPPORTED: https://www.roman-britain.co.uk/places/goldsborough-signal-station/]; The surviving mound is square in plan [SUPPORTED: https://www.roman-britain.co.uk/places/goldsborough-signal-station/]; The mound is about 30 m across [SUPPORTED: https://www.roman-britain.co.uk/places/goldsborough-signal-station/]; The mound stands about 1.4 m high [SUPPORTED: https://www.roman-britain.co.uk/places/goldsborough-signal-station/]; The site was excavated in 1918 [SUPPORTED: https://www.roman-britain.co.uk/places/goldsborough-signal-station/]; The excavation inside the tower found two human skeletons, a short thick-set man and a taller man [SUPPORTED: https://www.maltonmuseum.co.uk/2021/05/29/the-fortlets-signal-stations-along-the-yorkshire-coast/]; A large dog was found beneath the men [SUPPORTED: https://www.maltonmuseum.co.uk/2021/05/29/the-fortlets-signal-stations-along-the-yorkshire-coast/]; The dog''s head lay against one man''s throat, its paws across his shoulders [SUPPORTED: https://www.maltonmuseum.co.uk/2021/05/29/the-fortlets-signal-stations-along-the-yorkshire-coast/]"}]'::jsonb),
