eritage [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('19aa5815-9965-43b3-a2d9-e35190fd50ec'::uuid, 'card_description', 'Gran Saposoa: ruins in the Andean cloud forests, brought to attention by Gene Savoy in 1999. Scholars dispute his claims: Muscutt and Schjellerup had located them in the mid-1990s.', NULL, 'teaser-card-s032-rollback:19aa5815-9965-43b3-a2d9-e35190fd50ec:card_description', 'rollback of teaser-card-s032: card_description None restored on Gran Saposoa', '652c1a355bfc584f9dfcec1dab416a5567be886a07d7fd6ffd1475f4ba096d49|d742040eaca72813b20aef9c925a9a8aa3911efd7b411a0bab86cc9ad894b9cd|d742040eaca72813b20aef9c925a9a8aa3911efd7b411a0bab86cc9ad894b9cd', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Gran Saposoa: ruins in the Andean cloud forests, brought to attention by Gene Savoy in 1999. Scholars dispute his claims: Muscutt and Schjellerup had located them in the mid-1990s."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Gran Saposoa is a series of ruins in the Andean cloud forests [S1]; Gene Savoy brought the ruins to attention in 1999 [S1]; scholars dispute Savoy''s claims [S2]; the sites had previously been located by Muscutt and Schjellerup in the mid-1990s [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Gran Saposoa is a series of ruins in the Amazonas region of Peru, named by the American explorer Gene Savoy [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Saposoa]; The ruins lie in the Andean cloud forests [SUPPORTED: https://es.wikipedia.org/wiki/Gran_Saposoa]; Gene Savoy announced the site in 1999 [SUPPORTED: https://pt.wikipedia.org/wiki/Gran_Saposoa]; Professional archaeologists disputed Savoy''s claims, exposing the sizes and populations claimed for Gran Saposoa as grossly exaggerated [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Saposoa]; The sites had already been located and published by the archaeologist Keith Muscutt before Savoy''s announcement [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Saposoa]; The sites were located in the mid 1990s [SUPPORTED: https://en.wikipedia.org/wiki/Gran_Saposoa]"}]'::jsonb),
    ('19e287b4-3f69-4145-8f8e-4e214d8bb954'::uuid, 'card_description', 'An Iron Age hill fort 3 miles north west of Wiveliscombe: Clatworthy Camp is an Ancient Monument on the Heritage at Risk Register, vulnerable to scrub and tree growth.', NULL, 'teaser-card-s032-rollback:19e287b4-3f69-4145-8f8e-4e214d8bb954:card_description', 'rollback of teaser-card-s032: card_description None restored on Clatworthy Camp', '2d93255f8a5ab6f05d0e3376adf0153828b669e048eb99e18d5c2826102402f1|b75f4d9b1317bd61d495a8872d9a5b485c1a65358baf04d5edb751c19a495520|b75f4d9b1317bd61d495a8872d9a5b485c1a65358baf04d5edb751c19a495520', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-003", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "An Iron Age hill fort 3 miles north west of Wiveliscombe: Clatworthy Camp is an Ancient Monument on the Heritage at Risk Register, vulnerable to scrub and tree growth."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Clatworthy Camp is an Iron Age hill fort [S1]; it lies 3 miles north west of Wiveliscombe [S1]; it has been scheduled as an Ancient Monument [S2]; it is on the Heritage at Risk Register [S2]; it is vulnerable to scrub and tree growth [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Clatworthy Camp is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Clatworthy_Camp]; It lies 3 miles north west of Wiveliscombe [SUPPORTED: https://en.wikipedia.org/wiki/Clatworthy_Camp]; It is a scheduled Ancient Monument [SUPPORTED: https://en.wikipedia.org/wiki/Clatworthy_Camp]; It is on the Heritage at Risk Register [SUPPORTED: https://en.wikipedia.org/wiki/Clatworthy_Camp]; It is on the Heritage at Risk Register because of its v