    ('1ae9f44c-ebe7-454c-8c55-58efe28c0376'::uuid, 'card_description', 'Destroyed by earthquake around 1700 BC, the Minoan temple of Anemospilia on Mount Juktas held a young man on an altar with a bronze blade, read as sacrifice, still debated.', NULL, 'teaser-card-s032-rollback:1ae9f44c-ebe7-454c-8c55-58efe28c0376:card_description', 'rollback of teaser-card-s032: card_description None restored on Anemospilia', '971fcafa8d18d25c0c0af9fb0d80e14761b74f15562e85c8bd36474afba200b5|b443dde32d88265b4fd96648b7f32551e481f49552011752a963dc10df5d4e21|b443dde32d88265b4fd96648b7f32551e481f49552011752a963dc10df5d4e21', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-003", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Destroyed by earthquake around 1700 BC, the Minoan temple of Anemospilia on Mount Juktas held a young man on an altar with a bronze blade, read as sacrifice, still debated."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site was destroyed by earthquake around 1700 BC [S3]; Anemospilia is a Minoan temple on Mount Juktas [S1]; a young man was found on an altar with a bronze blade [S3]; excavators read this as human sacrifice [S3]; that interpretation is still debated [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-009b (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Anemospilia is the site of an ancient Minoan temple on Crete [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]; The temple stands on Mount Juktas [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]; The temple was destroyed by earthquake around 1700 BC [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]; A young man, an 18-year-old male, was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]; His body lay on a stone platform in the western chamber [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]; An engraved knife or blade was found among his bones [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]; The blade with the young man was made of bronze [UNVERIFIABLE, no proving quote: None]; The site has been read as a place of human sacrifice [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]; That reading is disputed by some archaeologists [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]; The platform the young man lay on is not accepted by all as an altar [SUPPORTED: https://en.wikipedia.org/wiki/Anemospilia]"}]'::jsonb),
    ('1bc1ab56-9d6f-478e-a4aa-76bdd91f61ee'::uuid, 'card_description', 'Quriwayrachina, an Inca-period site in Peru''s Ayacucho Region, keeps two platforms, Hatun Quri Wayrachina and Huch''uy Quri Wayrachina, near the mountain Inka Pallanka, venerated as an apu.', NULL, 'teaser-card-s032-rollback:1bc1ab56-9d6f-478e-a4aa-76bdd91f61ee:card_description', 'rollback of teaser-card-s032: card_description None restored on Quriwayrachina, Ayacucho', '3c23c599213b34d2e2a2239ac42ae936d3763be0dd7f7b503fc13c28d5649510|0e24f64393da7af7a3c66ca091e09d5f17d3b8230dd9d8fcddb78cdbf681ec73|0e24f64393da7af7a3c66ca091e09d5f17d3b8230dd9d8fcddb78cdbf681ec73', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Quriwayrachina, an Inca-period site in Peru''s Ayacucho Region, keeps two platforms, Hatun Quri Wayrachina and Huch''uy Quri Wayrachina, near the mountain Inka Pallanka, venerated as an apu."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "it is an Inca-period archaeological site in Peru''s Ayacucho Region [S1]; it has two platforms, Hatun Quri Wayrachina and Huch''uy Quri Wayrachina [S3]; it sits near the mountain Inka Pallanka [S2]; that mountain is venerated as an apu [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Quriwayrachina (Ayacucho) is an Inca-period archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Quriwayrachina,_Ayacucho]; The site is in Peru, in the Ayacucho Region, Lucanas Province, Carmen Salcedo District [SUPPORTED: https://en.wikipedia.org/wiki/Quriwayrachina,_Ayacucho]; The site lies near the mountain Inka Pallanka [SUPPORTED: https://en.wikipedia.org/wiki/Quriwayrachina,_Ayacucho]; Inka Pallanka is venerated as an apu by the people of the area [SUPPORTED: https://en.wikipedia.org/wiki/Quriwayrachina,_Ayacucho]; The site has two platforms [SUPPORTED: https://en.wikipedia.org/wiki/Quriwayrachina,_Ayacucho]; The two platforms are called Hatun Quri Wayrachina and Huch''uy Quri Wayrachina [SUPPORTED: https://en.wikipedia.org/wiki/Quriwayrachina,_Ayacucho]"}]'::jsonb),
    ('1c0b4493-7302-4c4b-a126-a91e9b27305e'::uuid, 'card_description', NULL, 'Double-ditched hilltop fort above the River Wye in Herefordshire, enclosing 4 hectares. The name derives from Celtic words meaning "lookout" and "flat-topped ridge."', 'teaser-card-s032-rollback:1c0b4493-7302-4c4b-a126-a91e9b27305e:card_description', 'rollback of teaser-card-s032: card_description ''Double-ditched hilltop fort above the River Wye in Herefordshire, enclosing 4 hectares. The name derives from Celtic words meaning "lookout" and "flat-topped ridge."'' restored on Capler Camp', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('1d6c490a-ef60-42ae-85d8-4ba27c1b8d3e'::uuid, 'card_description', NULL, 'Completed in 105 AD, this bridge over the Danube was likely the longest arch bridge in the world for over 1,000 years. It was deliberately destroyed to stop barbarian crossings.', 'teaser-card-s032-rollback:1d6c490a-ef60-42ae-85d8-4ba27c1b8d3e:card_description', 'rollback of teaser-card-s032: card_description ''Completed in 105 AD, this bridge over the Danube was likely the longest arch bridge in the world for over 1,000 years. It was deliberately destroyed to stop barbarian crossings.'' restored on Trajan''s Bridge', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('1e8b10e4-1124-4f35-9557-27a57d7dc4a1'::uuid, 'card_description', 'Along the old road from Methone to Dion, the Necropolises of Pydna hold Macedonian tombs from the Bronze Age to the early Christian period; smaller tumuli are lost to erosion.', NULL, 'teaser-card-s032-rollback:1e8b10e4-1124-4f35-9557-27a57d7dc4a1:card_description', 'rollback of teaser-card-s032: card_description None restored on Necropolises of Pydna', '0098b26b8e1e6f2e04b0f0942d22ef84411ed538c68e21e885dc3aff0cc26fc1|6f3072a02c41cd70ddca7f85cb361756258702f1241e359f85664b275e22ddb0|6f3072a02c41cd70ddca7f85cb361756258702f1241e359f85664b275e22ddb0', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-003", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Along the old road from Methone to Dion, the Necropolises of Pydna hold Macedonian tombs from the Bronze Age to the early Christian period; smaller tumuli are lost to erosion."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the necropolises lie along the road connecting Methone to Dion [S1]; they contain Macedonian tombs [S1]; the burials range from the Bronze Age to the early Christian period [S2]; smaller tumuli have been lost to erosion [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-009b (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Necropolises of Pydna are burial grounds of tombs around the ancient city of Pydna [SUPPORTED: https://en.wikipedia.org/wiki/Necropolises_of_Pydna]; They lie beside the ancient road running from Methone in the north to Dion in the south [SUPPORTED: https://en.wikipedia.org/wiki/Necropolises_of_Pydna]; The necropolises contain Macedonian tombs [SUPPORTED: https://en.wikipedia.org/wiki/Necropolises_of_Pydna]; The oldest tombs date from the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Necropolises_of_Pydna]; The youngest tombs date from the early Christian period [SUPPORTED: https://en.wikipedia.org/wiki/Necropolises_of_Pydna]; Smaller tumuli have eroded over time and are no longer visible [SUPPORTED: https://en.wikipedia.org/wiki/Necropolises_of_Pydna]"}]'::jsonb),
    ('1ed8dbd5-c97e-4f93-8eab-af98444a64de'::uuid, 'card_description', 'Desfina is a town in southern Phocis. On the hill of Kastrouli nearby, a fortified Mycenaean settlement of the 13th-12th century BC has been tentatively identified with Homeric Anemoreia.', NULL, 'teaser-card-s032-rollback:1ed8dbd5-c97e-4f93-8eab-af98444a64de:card_description', 'rollback of teaser-card-s032: card_description None restored on Desfina', '59edb8e94f672a2e994ae84f039c9ff69847541cab876ed26bbbab8cff15583e|ac9162da126798304a2a7c69976b0618ba283bb945441001efa3b75c9d5a981b|ac9162da126798304a2a7c69976b0618ba283bb945441001efa3b75c9d5a981b', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Desfina is a town in southern Phocis. On the hill of Kastrouli nearby, a fortified Mycenaean settlement of the 13th-12th century BC has been tentatively identified with Homeric Anemoreia."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Desfina is a town in southern Phocis [S1]; on the hill of Kastrouli nearby there is a fortified Mycenaean settlement of the 13th-12th century BC [S2]; that settlement has been tentatively identified with Homeric Anemoreia [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Desfina is a town in southern Phocis, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Desfina]; The Mycenaean settlement is at Kastrouli, 4 km east of Desfina [SUPPORTED: https://en.wikipedia.org/wiki/Anemoreia]; The settlement is fortified, with Cyclopean masonry of the Late Helladic III period [SUPPORTED: https://kastrouli.wordpress.com/]; The settlement was occupied from at least LH IIIB2 until its destruction in LH IIIC Middle, ca. 1100 BC, i.e. the 13th-12th century BC [SUPPORTED: https://kastrouli.wordpress.com/]; The Mycenaean ruins of Kastrouli have been identified with Homeric Anemoreia [SUPPORTED: https://en.wikipedia.org/wiki/Desfina]; The identification with Anemoreia is tentative: Anemoreia''s exact location is not known with certainty [SUPPORTED: https://en.wikipedia.org/wiki/Anemoreia]; Kastrouli is a hill on which the settlement stands [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('1ef25b31-5c42-4ee6-aae1-1bd9c2640bff'::uuid, 'card_description', 'Near the Areni village along the Arpa River, Areni-1 Cave gave up the earliest known shoe in the world, the oldest humanoid brain, and a straw skirt dating to 3,900 years BCE.', NULL, 'teaser-card-s032-rollback:1ef25b31-5c42-4ee6-aae1-1bd9c2640bff:card_description', 'rollback of teaser-card-s032: card_description None restored on Areni-1 Cave', '11542f8b04ca7462245521679f00158c51c28be3f9882c5799507b57efa3d744|abea90530c870eafc5e434d5316ac1e7db0a38bca95d7db8d58ccb482ea1d6ce|abea90530c870eafc5e434d5316ac1e7db0a38bca95d7db8d58ccb482ea1d6ce', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-003", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Near the Areni village along the Arpa River, Areni-1 Cave gave up the earliest known shoe in the world, the oldest humanoid brain, and a straw skirt dating to 3,900 years BCE."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the cave complex lies near the Areni village along the Arpa River [S1]; the earliest known shoe in the world was found at the site [S2]; the oldest humanoid brain was discovered in the cave [S5]; a straw skirt dating to 3,900 years BCE was reported [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-009b (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Areni-1 cave is an ancient archaeological site in Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Areni-1_Cave]; It lies near the Areni village in southern Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Areni-1_Cave]; It lies along the Arpa River [SUPPORTED: https://en.wikipedia.org/wiki/Areni-1_Cave]; The earliest known shoe in the world was discovered at the site [SUPPORTED: https://en.wikipedia.org/wiki/Areni-1_Cave]; The oldest humanoid brain was discovered in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Areni-1_Cave]; A straw skirt dating to 3,900 years BCE was reported from the site [SUPPORTED: https://en.wikipedia.org/wiki/Areni-1_Cave]"}]'::jsonb),
    ('20f12dcd-f2a7-4014-9dce-160c90b27749'::uuid, 'card_description', 'A Roman road ran from Poetovio in the north to Siscia in the south, and Pyrri stood along it in Pannonia. Evidence suggests the settlement lies under the village of Komin today.', NULL, 'teaser-card-s032-rollback:20f12dcd-f2a7-4014-9dce-160c90b27749:card_description', 'rollback of teaser-card-s032: card_description None restored on Pyrri', '6e0f554026ad62f36787a77c2a47746c7b0e51553bc8ab71a5c96bfb52552757|664e7cf3be5ac96e4905d94f73f4059718009e51a7d1df168049700782dccbdd|664e7cf3be5ac96e4905d94f73f4059718009e51a7d1df168049700782dccbdd', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-004", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "A Roman road ran from Poetovio in the north to Siscia in the south, and Pyrri stood along it in Pannonia. Evidence suggests the settlement lies under the village of Komin today."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "a road ran from Poetovio in the north to Siscia in the south [S1]; Pyrri stood along that road [S1]; Pyrri lay in the Roman province of Pannonia [S1]; Pyrri was a Roman settlement [S1]; evidence suggests the settlement corresponds to the present-day village of Komin [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Pyrri was an ancient Roman settlement (the central claim: what kind of place the site is) [SUPPORTED: https://en.wikipedia.org/wiki/Pyrri]; The settlement lay in Pannonia [SUPPORTED: https://en.wikipedia.org/wiki/Pyrri]; Pyrri stood along a road that connected Poetovio [SUPPORTED: https://en.wikipedia.org/wiki/Pyrri]; That road ran from Poetovio in the north to Siscia in the south [SUPPORTED: https://en.wikipedia.org/wiki/Pyrri]; The settlement is believed to lie at the present-day village of Komin, in Croatia [SUPPORTED: https://en.wikipedia.org/wiki/Pyrri]"}]'::jsonb),
    ('211bbc3a-1c61-4c8c-b5c2-0e49e027c18a'::uuid, 'card_description', 'Near the modern village of Korinos, on the site of ancient Pydna, the Macedonian Tombs hold Tomb A, discovered in the mid-19th century, and a second smaller grave, Tomb B, found in 1991.', NULL, 'teaser-card-s032-rollback:211bbc3a-1c61-4c8c-b5c2-0e49e027c18a:card_description', 'rollback of teaser-card-s032: card_description None restored on Macedonian Tombs, Korinos', '6ce56fdcca3cff430597d525b9e8ba471d692c427b326add8af00bac264a746c|3e4365f42c5bf0d12ff51936eb120e5c4564909cbc4d10a1b52805daeedf78fd|3e4365f42c5bf0d12ff51936eb120e5c4564909cbc4d10a1b52805daeedf78fd', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-004", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Near the modern village of Korinos, on the site of ancient Pydna, the Macedonian Tombs hold Tomb A, discovered in the mid-19th century, and a second smaller grave, Tomb B, found in 1991."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the tombs are near the modern village of Korinos [S1]; the tombs stand on the site of ancient Pydna [S1]; the group includes Tomb A [S1, S2]; the group includes a second, smaller grave, Tomb B [S1, S3]; Tomb A was discovered in the mid-19th century [S2]; Tomb B was discovered in 1991 [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The site holds two Macedonian tombs, Tomb A and Tomb B (the central claim: what kind of place the site is) [SUPPORTED: https://en.wikipedia.org/wiki/Macedonian_Tombs,_Korinos]; The tombs are near the modern village of Korinos [SUPPORTED: https://en.wikipedia.org/wiki/Macedonian_Tombs,_Korinos]; The tombs stand on the site of ancient Pydna [SUPPORTED: h