    ('217706bc-155b-44ca-bd4b-9df96e3bc014'::uuid, 'card_description', 'Kʼaxob was a Maya site in Belize, occupied from about 800 BC to AD 900. It began as a village and grew through the Early to Late Classic Periods into household mounds and plazas.', NULL, 'teaser-card-s032-rollback:217706bc-155b-44ca-bd4b-9df96e3bc014:card_description', 'rollback of teaser-card-s032: card_description None restored on Kʼaxob', '6d003672d7f8bde6ecb0264fece0a913b059d315fdf7fc1dd430448690f03fb3|7b93b9147171eb038e1065eb8d465dd48d152ef4362f1f6e2e3f42f95391184c|7b93b9147171eb038e1065eb8d465dd48d152ef4362f1f6e2e3f42f95391184c', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-004", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Kʼaxob was a Maya site in Belize, occupied from about 800 BC to AD 900. It began as a village and grew through the Early to Late Classic Periods into household mounds and plazas."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Kʼaxob is a Maya site in Belize [S1]; Kʼaxob was occupied from about 800 BC to AD 900 [S1]; the site began as a village [S2]; the site expanded during the Early to Late Classic Periods [S2]; the complex includes household mounds [S4]; the complex includes plazas [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Kʼaxob is a Maya archaeological site (the central claim: what kind of place the site is) [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCaxob]; The site is in Belize [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCaxob]; It was occupied from about 800 BC to AD 900 [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCaxob]; It began as a village site [SUPPORTED: https://en.wikipedia.org/wiki/K%CA%BCaxob]; It gr