    ('217b6292-d8ee-403b-a8ad-236304ac481d'::uuid, 'card_description', NULL, 'Two sets of human footprints in the Cuatrociénegas Basin, dated to 10,550 and 7,240 years ago. The older is the earliest known in Mexico; the younger forms a trackway of 11 in-situ prints.', 'teaser-card-s032-rollback:217b6292-d8ee-403b-a8ad-236304ac481d:card_description', 'rollback of teaser-card-s032: card_description ''Two sets of human footprints in the Cuatrociénegas Basin, dated to 10,550 and 7,240 years ago. The older is the earliest known in Mexico; the younger forms a trackway of 11 in-situ prints.'' restored on Cuatro Cienegas Footprints', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('21d9af3d-9d4e-4df0-beb1-268486146a61'::uuid, 'card_description', 'In the Ayacucho Region of Peru, Hatun Usnu means big usnu in Quechua: a pyramid-shaped, terraced ceremonial platform the Incas used for rituals involving liquid offerings.', NULL, 'teaser-card-s032-rollback:21d9af3d-9d4e-4df0-beb1-268486146a61:card_description', 'rollback of teaser-card-s032: card_description None restored on Hatun Usnu', '12d27a28d9b47ed81fa0f9e10cc1c1f01ba2cfe0af90cb3fa23aa7605b9b2c62|b75eb1bf653714b8ec2d9d1e633d61449c01708d83d29dde437e176c45ff317d|b75eb1bf653714b8ec2d9d1e633d61449c01708d83d29dde437e176c45ff317d', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-004", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "In the Ayacucho Region of Peru, Hatun Usnu means big usnu in Quechua: a pyramid-shaped, terraced ceremonial platform the Incas used for rituals involving liquid offerings."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site lies in the Ayacucho Region of Peru [S1]; the name means ''big usnu'' in Quechua [S2]; it is a pyramid-shaped, terraced ceremonial platform [S2]; the Incas used it [S2]; it was used for rituals involving liquid offerings [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Hatun Usnu is an archaeological site in Peru (the central claim: what kind of place the site is) [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_Usnu]; It lies in the Ayacucho Region of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_Usnu]; In Quechua hatun means big and usnu means altar, so the name means big usnu [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_Usnu]; It is a ceremonial platform [SUPPORTED: https://en.wikipedia.org/wiki/Hatun_U