    ('24de1fb5-935c-4fc0-89d0-00539a0ce610'::uuid, 'card_description', NULL, 'Paro stood 10 m tall and weighed over 80 tonnes — the largest moai ever raised. It fell around 1840, cracking in two. Its 10-tonne pukao headdress still lies at its head.', 'teaser-card-s032-rollback:24de1fb5-935c-4fc0-89d0-00539a0ce610:card_description', 'rollback of teaser-card-s032: card_description ''Paro stood 10 m tall and weighed over 80 tonnes — the largest moai ever raised. It fell around 1840, cracking in two. Its 10-tonne pukao headdress still lies at its head.'' restored on Te Pito Kura', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
