    ('2ad2ae09-19fb-4994-8f1d-33d84694c5fb'::uuid, 'card_description', 'Near Porodin, near Bitola, the Neolithic settlement of Veluška Tumba is a raised mound shaped like a truncated cone, 250 m long and 150 m wide, holding a cultural layer four metres thick.', NULL, 'teaser-card-s032-rollback:2ad2ae09-19fb-4994-8f1d-33d84694c5fb:card_description', 'rollback of teaser-card-s032: card_description None restored on Veluška Tumba', 'ad98fe14b63257d21e34795c0b7f3abac090a6f0d3c5de28c1dccdac8d1fe621|4fd959734c6f275402fe9ecccb8cfcc5f319536ff6a724c970c53216f9a19710|4fd959734c6f275402fe9ecccb8cfcc5f319536ff6a724c970c53216f9a19710', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-004", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Near Porodin, near Bitola, the Neolithic settlement of Veluška Tumba is a raised mound shaped like a truncated cone, 250 m long and 150 m wide, holding a cultural layer four metres thick."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site lies near the village of Porodin [S1]; the site lies near Bitola [S1]; it is a Neolithic settlement [S1]; it is an artificially raised mound shaped like a truncated cone [S2]; the mound is 250 m long [S3]; the mound is 150 m wide [S3]; it holds a cultural layer four metres thick [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Veluška Tumba is a Neolithic settlement (a dwelling site of Neolithic times) [SUPPORTED: https://mk.wikipedia.org/wiki/%D0%92%D0%B5%D0%BB%D1%83%D1%88%D0%BA%D0%B0_%D0%A2%D1%83%D0%BC%D0%B1%D0%B0]; It is an archaeological site in the Bitola village of Velušina [SUPPORTED: https://mk.wikipedia.org/wiki/%D0%92%D0%B5%D0%BB%D1%83%D1%88%D0%BA%D0%B0_%D0%A2%D1%83%D0%B