    ('2da0bfc3-cc20-444a-bfa7-bf23642ecb0b'::uuid, 'card_description', 'On the Desna River bank, Mezine holds Ukraine''s most Paleolithic artifact finds: bracelets engraved with marks possibly marking lunar cycles, and the earliest known meander pattern.', NULL, 'teaser-card-s032-rollback:2da0bfc3-cc20-444a-bfa7-bf23642ecb0b:card_description', 'rollback of teaser-card-s032: card_description None restored on Mezine', '81a385f823f96ea07a6119a995f2d02158b8b3163db31ba4a0993eb37b02a3e1|e469b1837bc238c46c43f03a926784111d4643f1779bcfcc76e5a729f16fc7a6|e469b1837bc238c46c43f03a926784111d4643f1779bcfcc76e5a729f16fc7a6', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-004", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "On the Desna River bank, Mezine holds Ukraine''s most Paleolithic artifact finds: bracelets engraved with marks possibly marking lunar cycles, and the earliest known meander pattern."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the site lies on the Desna River bank [S1]; it holds the most Paleolithic artifact finds in Ukraine [S2]; bracelets engraved with marks possibly representing lunar calendar cycles were found there [S3]; an object carrying the earliest known example of a meander pattern was found there [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Mezine is an archaeological site in Ukraine located on the bank of the Desna River [SUPPORTED: https://en.wikipedia.org/wiki/Mezine]; Mezine holds Ukraine''s greatest number of finds from the Paleolithic period [SUPPORTED: https://en.wikipedia.org/wiki/Mezine]; Bracelets engraved with marks were found at Mezine [SUPPORTED: https://en.wikipedia.org/wiki/Mezine]; The marks on the bracelets possibly represent calendar lunar cycles [SUPPORTED: https://en.wikipedia.org/wiki/Mezine]; The earliest known example of a meander pattern was found near Mezine [SUPPORTED: https://en.wikipedia.org/wiki/Mezine]"}]'::jsonb),
