    ('34d5b282-ab84-430a-90eb-6347f007fd2e'::uuid, 'card_description', NULL, 'In 180 BC, Rome forcibly transplanted 47,000 Ligurian tribespeople to Samnium. The territory they occupied — the Ligures Baebiani — became a distinct settled community within the Roman state.', 'teaser-card-s032-rollback:34d5b282-ab84-430a-90eb-6347f007fd2e:card_description', 'rollback of teaser-card-s032: card_description ''In 180 BC, Rome forcibly transplanted 47,000 Ligurian tribespeople to Samnium. The territory they occupied — the Ligures Baebiani — became a distinct settled community within the Roman state.'' restored on Ligures Baebiani', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
