    ('3d576cfb-2228-45a3-a05e-8433b80d88bc'::uuid, 'card_description', 'Along the Via Augusta, 6 km from ancient Tarraco, Torre dels Escipions rises, a Roman funerary tower of the early 1st century AD, likely a family mausoleum holding cremated remains.', NULL, 'teaser-card-s032-rollback:3d576cfb-2228-45a3-a05e-8433b80d88bc:card_description', 'rollback of teaser-card-s032: card_description None restored on Torre dels Escipions', '7dee2804bebd7a41c911206d9962a425c0565ab6e09be4b3dfc18e8e99a16542|a8b46d39329826c0172c11125abe9f7d1e287b1f66529546ee76498adcbd7407|a8b46d39329826c0172c11125abe9f7d1e287b1f66529546ee76498adcbd7407', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-005", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Along the Via Augusta, 6 km from ancient Tarraco, Torre dels Escipions rises, a Roman funerary tower of the early 1st century AD, likely a family mausoleum holding cremated remains."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the tower stands along the Via Augusta [S1]; it is 6 km from ancient Tarraco [S1]; it is a Roman funerary tower [S1]; it was built in the early 1st century AD [S1]; it likely served as a family mausoleum [S2]; it housed cremated remains [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Torre dels Escipions is a funerary tower (a tower-shaped tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Torre_dels_Escipions]; It was built by the Romans, i.e. it is a Roman monument [SUPPORTED: https://en.wikipedia.org/wiki/Torre_dels_Escipions]; It stands beside the Via Augusta [SUPPORTED: https://www.mnat.cat/en/tower-of-the-scipios/]; It lies about 6 km from ancient Tarraco [SUPPORTED: https://en.wikipedia.or