    ('3f793103-342f-40ca-a0fa-96b1065ad986'::uuid, 'card_description', NULL, 'Built 1435–1425 BC in the final decade of Thutmose III''s reign at Deir el-Bahari, above Hatshepsut''s temple. Destroyed by earthquake in the 21st Dynasty — wall reliefs survive as painted fragments.', 'teaser-card-s032-rollback:3f793103-342f-40ca-a0fa-96b1065ad986:card_description', 'rollback of teaser-card-s032: card_description "Built 1435–1425 BC in the final decade of Thutmose III''s reign at Deir el-Bahari, above Hatshepsut''s temple. Destroyed by earthquake in the 21st Dynasty — wall reliefs survive as painted fragments." restored on Temple of Thutmose III', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('3fe3b8d1-a2a0-4d11-8bed-68f33110fb57'::uuid, 'card_description', 'Strabo called Rudiae a Greek city. In the immediate outskirts of Lecce, its remains still show traces of an amphitheatre, a necropolis and two city walls built of tuff.', NULL, 'teaser-card-s032-rollback:3fe3b8d1-a2a0-4d11-8bed-68f33110fb57:card_description', 'rollback of teaser-card-s032: card_description None restored on Rudiae', 'ab5d89734a74b044d536a9dbacad88d19bd343197cff9330ad046af02e4d0ee4|914e08dc11ac97b10b6f60d1f4e42186014f6e3515006a6f050d7dbf6a851a0f|914e08dc11ac97b10b6f60d1f4e42186014f6e3515006a6f050d7dbf6a851a0f', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-006", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Strabo called Rudiae a Greek city. In the immediate outskirts of Lecce, its remains still show traces of an amphitheatre, a necropolis and two city walls built of tuff."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Strabo called Rudiae a Greek city [S1]; Rudiae is identified with the archaeological remains in the immediate outskirts of Lecce [S2]; those remains comprise traces of an amphitheatre [S3]; they comprise traces of a necropolis [S3]; they comprise traces of two city walls built of tuff [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Rudiae was an ancient human settlement, a city of the past [SUPPORTED: https://en.wikipedia.org/wiki/Rudiae]; Rudiae''s archaeological remains lie in the immediate outskirts of Lecce [SUPPORTED: https://en.wikipedia.org/wiki/Rudiae]; Strabo called Rudiae a Greek city [SUPPORTED: https://en.wikipedia.org/wiki/Rudiae]; The remains show traces of an amphitheatre [SUPPORTED: https://en.wikipedia.org/wiki/Rudi