    ('40acede4-eb32-4515-9ca4-b44145280678'::uuid, 'card_description', NULL, 'Remains of the monastery of Karabelli Sion in the Demre valley of Lycia. Stone walls and foundations still trace the footprint of this Byzantine religious complex in the landscape.', 'teaser-card-s032-rollback:40acede4-eb32-4515-9ca4-b44145280678:card_description', 'rollback of teaser-card-s032: card_description ''Remains of the monastery of Karabelli Sion in the Demre valley of Lycia. Stone walls and foundations still trace the footprint of this Byzantine religious complex in the landscape.'' restored on Karabal Belören Demre Antalya', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('40fc1723-7365-4fcc-aab8-46f47e4eff17'::uuid, 'card_description', 'The Devil''s Causeway is a Roman road in Northumberland: it branches off Dere Street north of Corbridge and runs approximately 55 miles north to Berwick-upon-Tweed.', NULL, 'teaser-card-s032-rollback:40fc1723-7365-4fcc-aab8-46f47e4eff17:card_description', 'rollback of teaser-card-s032: card_description None restored on Devil''s Causeway', 'e0773b1c34a30e8d0645bcf37b1c1b3dd5743c181ac8dd29756443a72406698f|2763ee1411518bce964bc2ad551801cb617d5f70e6a4ecd79f3432ebc06bc1b0|2763ee1411518bce964bc2ad551801cb617d5f70e6a4ecd79f3432ebc06bc1b0', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-006", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Devil''s Causeway is a Roman road in Northumberland: it branches off Dere Street north of Corbridge and runs approximately 55 miles north to Berwick-upon-Tweed."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Devil''s Causeway is a Roman road in Northumberland [S1]; it branches off Dere Street north of Corbridge [S2]; it runs approximately 55 miles north to Berwick-upon-Tweed [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Devil''s Causeway is a Roman road [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Causeway]; The Devil''s Causeway is in Northumberland [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Causeway]; It branches off Dere Street north of Corbridge [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Causeway]; It runs for approximately 55 miles (89 km) [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Causeway]; It runs north to Berwick-upon-Tweed [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Causew