    ('417b5d77-c70a-40ad-adad-7f92ef1a0544'::uuid, 'card_description', NULL, 'Remains of a Roman agora in active use from the 1st century BC through the 5th century AD. The marketplace served as the civic and commercial heart of the ancient city that once surrounded it.', 'teaser-card-s032-rollback:417b5d77-c70a-40ad-adad-7f92ef1a0544:card_description', 'rollback of teaser-card-s032: card_description ''Remains of a Roman agora in active use from the 1st century BC through the 5th century AD. The marketplace served as the civic and commercial heart of the ancient city that once surrounded it.'' restored on Roma Dönemi Agora Harabeleri', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
