    ('45ac8925-95ec-476a-9a36-9bbb650add84'::uuid, 'card_description', 'The House of Taga on Tinian held twelve prehistoric megaliths standing approximately 15 feet tall, each a base crowned by a hemispherical capstone. Only one still stands.', NULL, 'teaser-card-s032-rollback:45ac8925-95ec-476a-9a36-9bbb650add84:card_description', 'rollback of teaser-card-s032: card_description None restored on House of Taga', 'fa743b755c791bd8b89fb8a51d61899046c36fb3c2d897c492b8d9000906d3ab|55c37006123ca672ea2517164a80ff7659fde119fce2371a4e534e8335a77f9b|55c37006123ca672ea2517164a80ff7659fde119fce2371a4e534e8335a77f9b', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-006", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The House of Taga on Tinian held twelve prehistoric megaliths standing approximately 15 feet tall, each a base crowned by a hemispherical capstone. Only one still stands."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the House of Taga is on Tinian [S1]; it held twelve megaliths [S2]; the megaliths are prehistoric [S1]; each megalith stood approximately 15 feet tall [S2]; each megalith consisted of a base topped by a hemispherical capstone [S2]; only one pillar still stands [S4]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The House of Taga is an archaeological site of prehistoric megaliths on the island of Tinian in the Northern Mariana Islands [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Taga]; The megaliths are prehistoric [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Taga]; The site held twelve megaliths [SUPPORTED: https://en.wikipedia.org/wiki/House_of_Taga]; The megaliths stood approximately 15 feet tall [SUPPORTED: htt