    ('45c293d7-6d69-47e5-adec-68b8e1ce6ec0'::uuid, 'card_description', NULL, 'Ruins of Constantina, a Roman and Byzantine city on the Syrian frontier. An arch, cut stone blocks, and structural remains survive from the city known to the Assyrian population as Tella.', 'teaser-card-s032-rollback:45c293d7-6d69-47e5-adec-68b8e1ce6ec0:card_description', 'rollback of teaser-card-s032: card_description ''Ruins of Constantina, a Roman and Byzantine city on the Syrian frontier. An arch, cut stone blocks, and structural remains survive from the city known to the Assyrian population as Tella.'' restored on Çatalat Viranşehir Antik Kent', '||e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '[{"source": "lane WB run wb-cardgap-2026-10-07: no-description", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "no-description"}]'::jsonb),
    ('4656cc72-cea3-407e-a61c-314450ff6c62'::uuid, 'card_description', 'Dating to approximately 50 BC, Ringsbury Camp is an Iron Age multivallate hillfort whose double banks were built from non-local limestone rubble. Its inner bank rises 5 metres high.', NULL, 'teaser-card-s032-rollback:4656cc72-cea3-407e-a61c-314450ff6c62:card_description', 'rollback of teaser-card-s032: card_description None restored on Ringsbury Camp', 'b74f2aa9535f722ab1ec601937e27f7339be38ff61e326119f6156aed5996304|39089a066131efe1475323edc22f452479cf5377c15b7e915f096c9d9b905cba|39089a066131efe1475323edc22f452479cf5377c15b7e915f096c9d9b905cba', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-006", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Dating to approximately 50 BC, Ringsbury Camp is an Iron Age multivallate hillfort whose double banks were built from non-local limestone rubble. Its inner bank rises 5 metres high."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Ringsbury Camp dates to approximately 50 BC [S1]; it is an Iron Age multivallate hillfort [S1]; it has double banks [S2]; the banks were built from non-local limestone rubble [S3]; the inner bank rises 5 metres high [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Ringsbury Camp is an Iron Age hillfort in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Ringsbury_Camp]; The fort dates to approximately 50 BC [SUPPORTED: https://en.wikipedia.org/wiki/Ringsbury_Camp]; The fort is multivallate, with a double-banked structure [SUPPORTED: https://en.wikipedia.org/wiki/Ringsbury_Camp]; The banks were built from limestone rubble [SUPPORTED: https://en.wikipedia.org/wiki/Ringsbury_Camp]; The limes