    ('46838746-5160-40bb-a0e7-5bb88bd33db9'::uuid, 'card_description', 'Occupied from around 500 BC, Dzibilnocac grew into a Maya city whose Chenes facades are elaborately decorated, while the main Palace carries a distinct Rio Bec design.', NULL, 'teaser-card-s032-rollback:46838746-5160-40bb-a0e7-5bb88bd33db9:card_description', 'rollback of teaser-card-s032: card_description None restored on Dzibilnocac', 'a3225224ac71a69bc4c2060c36f1c34fe920d64b1fe16ad711d9aff1e7970a9a|69ca5d852b6f024ae945c7367bfe7e9bda70f8c6ce7706cf2d70850ae591dffb|69ca5d852b6f024ae945c7367bfe7e9bda70f8c6ce7706cf2d70850ae591dffb', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-006", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Occupied from around 500 BC, Dzibilnocac grew into a Maya city whose Chenes facades are elaborately decorated, while the main Palace carries a distinct Rio Bec design."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Dzibilnocac was occupied from around 500 BC [S2]; it grew into a Maya city [S1, S2]; its Chenes facades are elaborately decorated [S3]; the main Palace exhibits a distinct Rio Bec design [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Dzibilnocac is an archaeological Maya site located in Campeche, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Dzibilnocac]; The site was occupied from around 500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Dzibilnocac]; The site grew into a large Maya city in the Late Classic period [SUPPORTED: https://en.wikipedia.org/wiki/Dzibilnocac]; The main structure is built in the Chenes architectural style [SUPPORTED: https://en.wikipedia.org/wiki/Dzibilnocac]; Its facades are richly decorated [SUPPORTE