    ('46958435-223f-4648-93cc-153479b9c41c'::uuid, 'card_description', 'The Peterborough Petroglyphs, cut in the pre-Columbian era, are the largest collection of First Nations rock carvings in Ontario: shamans, animals, reptiles, possibly the Great Spirit.', NULL, 'teaser-card-s032-rollback:46958435-223f-4648-93cc-153479b9c41c:card_description', 'rollback of teaser-card-s032: card_description None restored on Peterborough Petroglyphs', 'f0e7ee09f2ab6d8471dd8233a81bcc16f0d9bf102bf4e16ccb078ffcaf4c4093|704bf3befe393427f126850c258553779fb19f79f28bc17b56f27ad4013d497e|704bf3befe393427f126850c258553779fb19f79f28bc17b56f27ad4013d497e', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-006", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The Peterborough Petroglyphs, cut in the pre-Columbian era, are the largest collection of First Nations rock carvings in Ontario: shamans, animals, reptiles, possibly the Great Spirit."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "the Peterborough Petroglyphs are the largest collection of First Nations rock carvings in Ontario [S1]; the carvings were cut in the pre-Columbian era [S2]; the images include shamans [S2]; the images include animals [S2]; the images include reptiles [S2]; the images possibly include the Great Spirit [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "The site is the Peterborough Petroglyphs, a place of First Nations rock carvings in Ontario, Canada [SUPPORTED: https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park]; The carvings form the Peterborough Petroglyphs National Historic Site of Canada [SUPPORTED: https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park]; The carvings were cut in the pre-Columbian era [SUPPORTED: https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park]; They are the largest collection of ancient First Nations rock carvings in Ontario [SUPPORTED: https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park]; The carvings depict shamans [SUPPORTED: https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park]; The carvings depict animals [SUPPORTED: https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park]; The carvings depict reptiles [SUPPORTED: https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park]; One figure possibly represents the Great Spirit [SUPPORTED: https://en.wikipedia.org/wiki/Petroglyphs_Provincial_Park]"}]'::jsonb),
    ('47c37ef9-98ee-41d8-879b-e78db06295da'::uuid, 'card_description', 'Phoenicians from Tyre revived Kition in the 9th century BC. Its Bamboula acropolis still shows ship sheds for triremes and a sanctuary dating to at least the 9th century BC.', NULL, 'teaser-card-s032-rollback:47c37ef9-98ee-41d8-879b-e78db06295da:card_description', 'rollback of teaser-card-s032: card_description None restored on Kition', 'ffa5876bdc986214f99d61da98c35f9856ec95480299466403d6928b61da3ddc|54d2adc1aa9602626183668fc75aa2d202d2e0fc109958caab063f99ca55c9fd|54d2adc1aa9602626183668fc75aa2d202d2e0fc109958caab063f99ca55c9fd', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-006", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Phoenicians from Tyre revived Kition in the 9th century BC. Its Bamboula acropolis still shows ship sheds for triremes and a sanctuary dating to at least the 9th century BC."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Phoenicians from Tyre revived Kition in the 9th century BC [S2]; the Bamboula acropolis still shows ship sheds for triremes [S3]; the Bamboula acropolis still shows a sanctuary dating to at least the 9th century BC [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Kition is an ancient city on the island of Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Kition]; The Phoenicians who took over Kition came from Tyre [SUPPORTED: https://en.wikipedia.org/wiki/Kition]; Phoenician settlers rebuilt and reused Kition''s sanctuaries in the 9th century BC, reviving the city [SUPPORTED: https://en.wikipedia.org/wiki/Kition]; Kition''s acropolis stood on Bamboula hill [SUPPORTED: https://en.wikipedia.org/wiki/Kition]; The Bamboula site has ship sheds [SUPPORTED: https://en.wikipedia.org/wiki/Kition]; The ship sheds had shipways on which triremes were hauled up to dry [SUPPORTED: https://en.wikipedia.org/wiki/Kition]; A sanctuary at the site dates from the 9th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Kition]"}]'::jsonb),
    ('480b7897-a76a-406c-9991-7c1c8228f905'::uuid, 'card_description', 'Vrelo Šarkamen spans 25 hectares on the slopes of Deli Jovan in eastern Serbia, a Roman residential and memorial complex with a mausoleum. Only ruins remain today.', NULL, 'teaser-card-s032-rollback:480b7897-a76a-406c-9991-7c1c8228f905:card_description', 'rollback of teaser-card-s032: card_description None restored on Vrelo Šarkamen', 'cc4dc008a029b9cccf6303e7a34a96d47b05960c6a6ffdc5bf66c5840322a7c2|fd57bd5fba663d61a91fd1888d8e5aa4e5fae209ffa42d1aa69a8c26e4f1eae7|fd57bd5fba663d61a91fd1888d8e5aa4e5fae209ffa42d1aa69a8c26e4f1eae7', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-write-006", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Vrelo Šarkamen spans 25 hectares on the slopes of Deli Jovan in eastern Serbia, a Roman residential and memorial complex with a mausoleum. Only ruins remain today."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Vrelo Šarkamen spans 25 hectares [S1]; it lies on the slopes of Deli Jovan in eastern Serbia [S1]; it is a Roman residential and memorial complex [S1]; it includes a mausoleum [S2]; only ruins remain today [S3]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Vrelo Sarkamen is a Roman residential (resident) and memorial complex that includes a mausoleum. [SUPPORTED: https://en.wikipedia.org/wiki/%C5%A0arkamen]; The site spans 25 hectares. [SUPPORTED: https://en.wikipedia.org/wiki/%C5%A0arkamen]; The complex lies on the slopes of Deli Jovan. [SUPPORTED: https://en.wikipedia.org/wiki/%C5%A0arkamen]; The site is in eastern Serbia. [SUPPORTED: https://en.wikipedia.org/wiki/%C5%A0arkamen]; Only ruins remain today. [SUPPORTED: https://en.wikipedia.org/wiki/%C5%A0arkamen]"}]'::jsonb),
    ('489ca9da-126d-463b-b792-a1b39a555e3e'::uuid, 'card_description', 'Treva is the historical name of a Roman-era settlement in Germany, first recorded by Claudius Ptolemy in the 2nd century AD. Under Augustus, Roman forces reached the Elbe.', NULL, 'teaser-card-s032-rollback:489ca9da-126d-463b-b792-a1b39a555e3e:card_description', 'rollback of teaser-card-s032: card_description None restored on Treva', '2c8b1177762d3546973b324c8a5745e8739d068d78b7298a14771a22d242e591|f2b89315e16f1b51d0bb29f53bcada6ab47651644355f5eba0a7def13ed99c3c|f2b89315e16f1b51d0bb29f53bcada6ab47651644355f5eba0a7def13ed99c3c', '[{"source": "lane WB run wb-cardgap-2026-10-07: writer teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Treva is the historical name of a Roman-era settlement in Germany, first recorded by Claudius Ptolemy in the 2nd century AD. Under Augustus, Roman forces reached the Elbe."}, {"source": "lane WB run wb-cardgap-2026-10-07: checker teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Treva is the historical name of a Roman-era settlement in Germany [S1]; it was first recorded by Claudius Ptolemy in the 2nd century AD [S1]; under Augustus, Roman forces reached the Elbe [S2]"}, {"source": "lane WB run wb-cardgap-2026-10-07: verifier teaser-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-cardgap-2026-10-07/OUTCOMES.jsonl", "quote": "Treva is the historical name of a settlement in Germany, at the site of modern Hamburg. [SUPPORTED: https://en.wikipedia.org/wiki/Treva]; The settlement was of the Roman era. [SUPPORTED: https://en.wikipedia.org/wiki/Treva]; Treva was first recorded by Claudius Ptolemy. [SUPPORTED: https://en.wikipedia.org/wiki/Treva]; That first record dates to the 2nd century AD. [SUPPORTED: https://en.wikipedia.org/wiki/Treva]; Under Augustus the Romans reached the Elbe river. [SUPPORTED: https://en.wikipedia.org/wiki/Treva]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 98;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s032-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s032-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s032-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 98 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('0025b0ba-fd74-4c08-96e3-acc17956aa44'::uuid, 'card_description', 'Excavated ground at the foot of Mount Meron exceeded six acres. Khirbet Shema holds a large Jewish village of the Roman and Byzantine periods, with its synagogue and mausoleum.'), ('003428cd-6046-41c9-a687-a8a2b392e19d'::uuid, 'card_description', 'At Church Stoke in eastern Montgomeryshire, a steep-sided volcanic hill rises to 370 metres. Roundton Hill has been a nature reserve of the Montgomeryshire Wildlife Trust since 1985.'), ('0047ae41-af8e-44e1-b196-4035f5860554'::uuid, 'card_description', 'Gonnus stood on the north side of the Peneius, near the entrance of the only two passes by which an enemy could enter Thessaly from the north. Xerxes I''s army came that way.'), ('006294ae-548b-40ac-9271-03a017df7217'::uuid, 'card_description', 'A causeway links El Tintal to El Mirador, the larger site. About 25 km northeast of Carmelita, El Tintal is the second-largest in the Mirador Basin, among the four largest in northern Petén.'), ('0088c7e5-4a78-4b89-945d-3d5c787818e5'::uuid, 'card_description', 'Near Linares, Castulo was occupied from the Neolithic period and by the 6th century BC was the chief settlement of the Oretani. Roman sources say the princess Himilce married Hannibal.'), ('00cb2c16-2b30-42ce-aeb0-b258761ea754'::uuid, 'card_description', 'Where the Exe and Lowman meet, Stone Age flint tools mark Tiverton, the town on two fords. Cranmore Castle, over 15 acres, possibly a livestock enclosure, market site or tribal oppidum.'), ('010c0b09-760b-44f6-ba68-1f0353c7b3e6'::uuid, 'card_description', 'An earthquake in 1821 revealed the Cave of Ardales in Malaga province, where over 1,000 paintings and engravings lie across the walls, the ceilings and the speleothems.'), ('018c0c9d-c85f-4ed9-86eb-8cf350ec83e7'::uuid, 'card_description', 'In Chinchaypujio District of Cusco, Pumawasi is a pre-Columbian rock art cave 22 m deep, 30 m wide and 19 m high. Ceramics and human bone remains show burial ground and ceremonial use.'), ('01914c11-fb33-4778-a0ef-fd616ff33b88'::uuid, 'card_description', 'Cumae, the first Greek colony on mainland Italy, was founded around 725 BC from Chalcis. Famed as the home of the Cumaean Sibyl, it holds a purported 130-metre underground corridor.'), ('01b50bc7-3e36-494e-9a91-fc4d60323ada'::uuid, 'card_description', 'Franchthi Cave overlooks Kiladha Bay, where finds trace the transition from Paleolithic hunter-gatherers to Neolithic farmers, with domesticated plants and animals appearing around 7,000 BC.'), ('01cdc8e2-56b7-4c9d-b6d0-68c290a65e55'::uuid, 'card_description', 'Near Sartène in the Sartenais region of southern Corsica, Apazzu is a prehistoric megalithic site. Excavations uncovered artifacts, among them a stone vase with a zoomorphic protome.'), ('01f3d961-e2cf-4a3d-bc36-7e9976efe93e'::uuid, 'card_description', '54 km southeast of Puno in the Titicaca Basin, Jisk''a Iru Muqu was occupied from circa 3400-1600 BCE. Excavations recovered obsidian tools, a gold necklace and early domestic architecture.'), ('0286a741-77f2-4148-8e62-487041920281'::uuid, 'card_description', 'In the district of Huayopata, La Convención Province, in the Cusco region of Peru, an archaeological site carries two spellings: Cochapata, also written Qochapata.'), ('036346d9-313c-4fcd-9649-1aaba368e72e'::uuid, 'card_description', NULL), ('03a7a357-12a8-40f9-ae6a-9cef78135fd3'::uuid, 'card_description', 'Dubris, on the site of Dover, became the main Roman cross-Channel port, taking over from Rutupiae. A 1970s bypass uncovered its remains; an eight-week excavation found a Roman mansio.'), ('04982451-5603-41cb-957d-758925170c8e'::uuid, 'card_description', 'M''Daourouch sits at the site of the ancient Berber-Roman town of Madauros in Numidia. Two names, one piece of ground: Madauros for the ancient town, M''Daourouch for the site standing there.'), ('057ed947-18f5-45f5-b4c6-6bc1e29264d7'::uuid, 'card_description', 'On a spur of Dinedor Hill, Dinedor Camp looks east to where the Wye meets the Lugg. In 1951 a trench was cut from the rampart edge about 35 metres towards the centre of the camp.'), ('05afa876-bd9b-4285-8aa3-cb1f71fb3707'::uuid, 'card_description', 'About 200 meters north of the Araz River, Ərəbyengicə is an ancient settlement whose finds include obsidian remains and combed-surface pottery of the Late Chalcolithic.'), ('05f23376-78dc-4cb6-941d-faaea3abe6aa'::uuid, 'card_description', 'Tindari''s Greek theater, built between the 4th and 3rd centuries BC, could seat 3,000 spectators. In the 1st century AD part of the cliff collapsed; earthquakes did more in the 4th century.'), ('06a44374-50d9-4bc1-b747-41fa09e28eee'::uuid, 'card_description', 'Near the village of Ninamaca, about 30 chullpas of pre-Inca times stand on top of a mountain at about 3,000 m. Ninamarca is possibly Quechua nina, fire, and marka, village: fire village.'), ('07947420-54ee-4cf5-ac06-47814ce7f56d'::uuid, 'card_description', 'Digging for a ferret in 1864, a gamekeeper uncovered Chedworth Roman Villa, one of the largest Roman villas found in Britain. Its west wing held a mosaic dining-room and two bathing suites.'), ('08861937-eb56-4be0-9fef-778754fcfc1d'::uuid, 'card_description', 'At Hartashen Megalithic Avenue, two avenues of basalt menhirs stand at an angle in three rows each, and the lines never meet. What the rows were for is unclear; the site has no firm dating.'), ('0b54890b-b30b-4836-9c8c-805cf88a4a21'::uuid, 'card_description', 'At the foot of the mountain Qayakuna, in the village of Quchaq north of the town Cerro de Pasco, Qaqapatan keeps its rock paintings high at approximately 3,782 metres.'), ('0bf5e631-0ee8-4b75-9c06-fd6d713cc42d'::uuid, 'card_description', 'Deriivka, a Copper Age site on the Dnieper, gave up a horse burial with apparent bit wear, first read as the earliest evidence of riding. Radiocarbon dating put the skull in the Iron Age.'), ('0cf46f86-7eea-46ec-bf6c-b803d3145000'::uuid, 'card_description', 'Four faces, four passages: the Arch of Janus is the only surviving quadrifrons arch in Rome, 16 m high in the Forum Boarium. Built from older spolia, it may honor Constantine I.'), ('0d801018-7183-44a3-97e4-136aa8a374ce'::uuid, 'card_description', 'Guellayhuasin is an archaeological site in Peru''s Pasco region, at an elevation of 3,167 m, northwest of the village of Pallanchacra. High Pasco ground, and a site marked out on it.'), ('0d938cf2-c77d-4741-83cb-c3413761d2c1'::uuid, 'card_description', 'Inside the Chiltern Hills, Ivinghoe keeps an Anglo-Saxon name glossed as ''Ifa''s hill-spur''. In 1086 the Domesday Book wrote it Evinghehou, and St Mary was burnt in 1234, rebuilt in 1241.'), ('0eaedf34-031e-4b8f-8fff-2db84a3e6da6'::uuid, 'card_description', 'Two monuments stand in the townland of Moylehid, County Fermanagh: the Eagle''s Knoll Cairn passage tomb and the Moylehid ring cairn, named from the Irish Mul-leithid, hill of breadth.'), ('0f654bf4-86b7-4602-8bee-c8da00f3edee'::uuid, 'card_description', NULL), ('0f7c84f4-7364-434d-b003-706c8d7a3275'::uuid, 'card_description', 'Cattle, deer, pig and goat bones lay beside the ceramics at Alampra, a Middle Bronze Age settlement of circa 1900-1650 BC in Cyprus, dug by John E. Coleman between 1974 and 1985.'), ('0fa4a18f-2bf1-4461-8538-0d6a071fab43'::uuid, 'card_description', 'Founded as a military camp near modern Razgrad, Abritus was a major Roman fortified city. Excavations there brought up Bulgaria''s largest Late Antique gold treasure: 835 coins weighing 4 kg.'), ('11ac5108-ad13-4b42-babc-ed1e298bebe3'::uuid, 'card_description', NULL), ('1203a68d-5c19-4f8e-828f-053129f79a63'::uuid, 'card_description', 'In the Kakheti region of Georgia, research at Ziari in Gurjaani Municipality has, since the 1960s, unearthed numerous stone artifacts, testifying to the presence of Paleolithic workshops.'), ('15f94167-4c6b-4d02-b46f-6b6dcb147c19'::uuid, 'card_description', 'Brewer''s Castle: a pear-shaped Iron Age enclosure just under 0.4 ha, the River Barle on three sides and Dane''s Brook to the south-west, on a steep, flat-topped knoll.'), ('160da9ec-9bc4-4893-8066-dd3afb41c5b2'::uuid, 'card_description', 'Chacamarca Historic Sanctuary: 2,500 hectares at approximately 4,105 metres, where patriot forces under Bolivar routed royalist troops on 6 August 1824, protecting Pumpush remains.'), ('16818a72-af8e-4397-a814-36c1502b27d3'::uuid, 'card_description', 'Papcastle was Derventio, a Roman fort built in timber and later rebuilt in stone. Excavations from 2010-2015 found one of the most complete Roman water mills in Britain.'), ('1758f6e8-4518-43fb-a14a-1ce52caca683'::uuid, 'card_description', 'By the EX-214 road, the Dolmen del prado de Lácara was built toward the end of the 4th millennium BC, or in the early 3rd millennium BC, among Extremadura''s most monumental megalithic sites.'), ('1803a375-2b6b-4335-b158-98a371ce8889'::uuid, 'card_description', 'On western Dartmoor, Merrivale holds double stone rows, the longest 263 metres, a circle of 11 granite stones about 18 metres across, and a standing menhir over 3 metres tall.'), ('184dfea2-b710-4c3a-a3e8-d8cea0738290'::uuid, 'card_description', 'On top of the mountain Allqu Willka in Ayacucho, Inka Raqay is an Inca site, and raqay in Quechua means a ruin, a shed, a storehouse, or a dormitory for farm laborers.'), ('18911cb2-dff1-4d14-9110-de55c40706c0'::uuid, 'card_description', 'Goldsborough keeps a square Roman signal mound, roughly 30 m across and 1.4 m high. Excavations in 1918 found two skeletons and a large dog inside, jaws at one man''s throat.'), ('1941620d-0f59-46a3-9e13-d10e9c05cdfa'::uuid, 'card_description', 'Cheqollo means nightingale in Quechua. Its pre-Hispanic site lies north of San Jeronimo in Peru''s Cusco Region, within a landscape of deep Inca and pre-Inca heritage.'), ('19aa5815-9965-43b3-a2d9-e35190fd50ec'::uuid, 'card_description', 'Gran Saposoa: ruins in the Andean cloud forests, brought to attention by Gene Savoy in 1999. Scholars dispute his claims: Muscutt and Schjellerup had located them in the mid-1990s.'), ('19e287b4-3f69-4145-8f8e-4e214d8bb954'::uuid, 'card_description', 'An Iron Age hill fort 3 miles north west of Wiveliscombe: Clatworthy Camp is an Ancient Monument on the Heritage at Risk Register, vulnerable to scrub and tree growth.'), ('1ae9f44c-ebe7-454c-8c55-58efe28c0376'::uuid, 'card_description', 'Destroyed by earthquake around 1700 BC, the Minoan temple of Anemospilia on Mount Juktas held a young man on an altar with a bronze blade, read as sacrifice, still debated.'), ('1bc1ab56-9d6f-478e-a4aa-76bdd91f61ee'::uuid, 'card_description', 'Quriwayrachina, an Inca-period site in Peru''s Ayacucho Region, keeps two platforms, Hatun Quri Wayrachina and Huch''uy Quri Wayrachina, near the mountain Inka Pallanka, venerated as an apu.'), ('1c0b4493-7302-4c4b-a126-a91e9b27305e'::uuid, 'card_description', NULL), ('1d6c490a-ef60-42ae-85d8-4ba27c1b8d3e'::uuid, 'card_description', NULL), ('1e8b10e4-1124-4f35-9557-27a57d7dc4a1'::uuid, 'card_description', 'Along the old road from Methone to Dion, the Necropolises of Pydna hold Macedonian tombs from the Bronze Age to the early Christian period; smaller tumuli are lost to erosion.'), ('1ed8dbd5-c97e-4f93-8eab-af98444a64de'::uuid, 'card_description', 'Desfina is a town in southern Phocis. On the hill of Kastrouli nearby, a fortified Mycenaean settlement of the 13th-12th century BC has been tentatively identified with Homeric Anemoreia.'), ('1ef25b31-5c42-4ee6-aae1-1bd9c2640bff'::uuid, 'card_description', 'Near the Areni village along the Arpa River, Areni-1 Cave gave up the earliest known shoe in the world, the oldest humanoid brain, and a straw skirt dating to 3,900 years BCE.'), ('20f12dcd-f2a7-4014-9dce-160c90b27749'::uuid, 'card_description', 'A Roman road ran from Poetovio in the north to Siscia in the south, and Pyrri stood along it in Pannonia. Evidence suggests the settlement lies under the village of Komin today.'), ('211bbc3a-1c61-4c8c-b5c2-0e49e027c18a'::uuid, 'card_description', 'Near the modern village of Korinos, on the site of ancient Pydna, the Macedonian Tombs hold Tomb A, discovered in the mid-19th century, and a second smaller grave, Tomb B, found in 1991.'), ('217706bc-155b-44ca-bd4b-9df96e3bc014'::uuid, 'card_description', 'Kʼaxob was a Maya site in Belize, occupied from about 800 BC to AD 900. It began as a village and grew through the Early to Late Classic Periods into household mounds and plazas.'), ('217b6292-d8ee-403b-a8ad-236304ac481d'::uuid, 'card_description', NULL), ('21d9af3d-9d4e-4df0-beb1-268486146a61'::uuid, 'card_description', 'In the Ayacucho Region of Peru, Hatun Usnu means big usnu in Quechua: a pyramid-shaped, terraced ceremonial platform the Incas used for rituals involving liquid offerings.'), ('221d4702-9626-4430-a71f-d5b70bcb9d4e'::uuid, 'card_description', NULL), ('22f53fa2-6170-4d7b-ac52-5904861bb47c'::uuid, 'card_description', 'Seven Barrows is a Bronze Age barrow cemetery at Upper Lambourn in Berkshire, England. Its unimproved chalk grassland supports over 100 herb species and a rich insect fauna.'), ('230e6523-3000-4234-a12e-1336ed82b012'::uuid, 'card_description', 'On Barbury Hill in Wiltshire, about 5.5 miles south of Swindon, the Iron Age hillfort of Barbury Castle keeps two deep defensive ditches and ramparts beside the ancient Ridgeway route.'), ('24de1fb5-935c-4fc0-89d0-00539a0ce610'::uuid, 'card_description', NULL), ('2726f1bb-9af6-4f23-af79-fc0f789a5ddc'::uuid, 'card_description', 'At the end of the 1-mile-long crag of the Whin Sill, Hadrian''s Wall runs over the fort at Housesteads, whose stone walls were built around AD 124 above a demolished turret.'), ('28fbf63d-5ca4-45fd-a54e-7a660232b148'::uuid, 'card_description', 'KaʼKabish lies in Belize''s Orange Walk District, near Lamanai, El Pozito and Blue Creek. Three neighbouring places, and the district in Belize that holds the site.'), ('2a9a96d5-f85c-4ff5-b2ef-1e92c5c9b6ca'::uuid, 'card_description', 'In Aosta in Italy, the Teatro Romano was built during the Julio-Claudian dynasty. Its 22-metre-high facade wall still towers over the city, and the theatre hosts performances today.'), ('2ad2ae09-19fb-4994-8f1d-33d84694c5fb'::uuid, 'card_description', 'Near Porodin, near Bitola, the Neolithic settlement of Veluška Tumba is a raised mound shaped like a truncated cone, 250 m long and 150 m wide, holding a cultural layer four metres thick.'), ('2b8e45c1-ca98-4c5f-8790-1b64f32e965f'::uuid, 'card_description', 'Near Southleigh in Devon, the Iron Age hillfort of Blackbury Camp encloses roughly 200 m by 100 m behind a rampart about 3 m high, and excavations uncovered over 1,000 slingstones.'), ('2c1d6960-56c3-425c-8bf5-199f40562a50'::uuid, 'card_description', 'On Menorca, Taula is a megalithic structure: a vertical pillar supporting a horizontal capstone, reaching heights of up to 5 metres. Its exact purpose remains unknown.'), ('2c437fa8-96cf-4451-b949-7e5c09889802'::uuid, 'card_description', 'A local landowner uncovered Huaca Esmeralda from the sand in 1923; the Chimu pyramid in Trujillo shows relief of fishing nets and fish on two platforms of approximately 65 by 41 meters.'), ('2cabb7a1-0596-457c-b37f-c041440b4fe2'::uuid, 'card_description', 'On the southwest slope of the Acropolis of Athens, the stone Odeon of Herodes Atticus was completed in AD 161. Its stands and orchestra were restored in Pentelic marble in the 1950s.'), ('2da0bfc3-cc20-444a-bfa7-bf23642ecb0b'::uuid, 'card_description', 'On the Desna River bank, Mezine holds Ukraine''s most Paleolithic artifact finds: bracelets engraved with marks possibly marking lunar cycles, and the earliest known meander pattern.'), ('2e547c1d-6f33-4342-b285-69b46d4a0b6e'::uuid, 'card_description', 'On the Piano di Tirena hill in Calabria, Terina lies between the Savuto and the Grande and matches a description Strabo wrote around 20 AD. Its coins and inscriptions rest in Lamezia Terme.'), ('317436c1-4827-4db2-acf6-1238452a5e86'::uuid, 'card_description', 'Remesiana lay beneath modern Bela Palanka on the Via Militaris, a major early Christian center under Bishop Nicetas. In 1987 it was declared an Archaeological Site of Great Importance.'), ('3191f287-4b47-4d83-903f-9815001086ed'::uuid, 'card_description', 'At Nausharo, 6 km from Mehrgarh, a pottery workshop gave up fired and unfired pottery, unworked clay and 12 flint blades or blade fragments, plus copper traces on two blade platforms.'), ('32a2b3eb-c4c3-4574-bbf5-30a4d7a68dfc'::uuid, 'card_description', 'In 1951 a quarry explosion exposed the Cave of Maltravieso in Caceres. Inside, 71 hands were stencilled onto the walls, together with linear designs and animal paintings.'), ('33f2b3eb-5fe2-444d-8168-807b81e17f2b'::uuid, 'card_description', 'Carn Brea, 1.6 km southwest of Redruth, crowns a hilltop in Cornwall, a fortified Neolithic settlement occupied between 3700 and 3400 BC, ringed by a 4.5-hectare outer rampart.'), ('34d5b282-ab84-430a-90eb-6347f007fd2e'::uuid, 'card_description', NULL), ('360da20f-8f95-4ba9-83fc-49d4b193b679'::uuid, 'card_description', 'Three sinkholes drop natural light into the nine chambers of the larger Padah-Lin cave. In the smaller rock shelter, red ochre hands, fish, bulls and bison mark the rock.'), ('365696cd-688a-412c-bb9f-66ff88fc7f35'::uuid, 'card_description', 'Gerrards Cross lies on the lower slopes of the Chiltern Hills near the River Misbourne, and the area around it holds Bulstrode Park Camp, an Iron Age fortified encampment.'), ('37999fa3-d22d-4c51-a2f5-fa0dd9d82942'::uuid, 'card_description', 'El Baúl, part of the Cotzumalhuapa Archaeological Zone, was occupied during the Formative stage; its southern acropolis was destroyed in 1997 and its main groups now lie under sugar cane.'), ('38aefc7c-1eb9-42d2-bd76-8d6b70847e35'::uuid, 'card_description', 'Kuélap stands on a limestone ridge at 3000 metres, its walls 10 to 20 m high and all but five of its 421 structures circular. It was rediscovered in 1843 by Juan Crisóstomo Nieto.'), ('3b348ad3-00f1-4d9a-9782-9006f4443cda'::uuid, 'card_description', 'On Exmoor, the turf-covered Bronze Age bowl barrow Alderman''s Barrow measures 24 by 22 meters and stands 1.4 meters high. In the 13th century it was called Osmunesburgh.'), ('3d576cfb-2228-45a3-a05e-8433b80d88bc'::uuid, 'card_description', 'Along the Via Augusta, 6 km from ancient Tarraco, Torre dels Escipions rises, a Roman funerary tower of the early 1st century AD, likely a family mausoleum holding cremated remains.'), ('3d68442a-8cd7-4679-8845-189db9470f27'::uuid, 'card_description', 'In northern Greece, Toumba is the Greek name for the mounds Bronze Age settlements left behind. What the settlements left in the ground, and the word the mounds carry.'), ('3dd0bac8-4618-4f61-a2b2-4dd229a76e45'::uuid, 'card_description', 'In a private front garden on the Islandmagee peninsula stands Ballylumford Dolmen, known locally as the Druid''s Altar: four upright stones under a heavy capstone, and a fallen stone inside.'), ('3efdc2f9-61ef-40b9-8d93-0f61668d8418'::uuid, 'card_description', 'Approximately 1.6 km south-west of Clevedon in North Somerset, Wain''s Hill is an Iron Age bivallate hillfort: linear earthwork banks and ditches on steep slopes.'), ('3f793103-342f-40ca-a0fa-96b1065ad986'::uuid, 'card_description', NULL), ('3fe3b8d1-a2a0-4d11-8bed-68f33110fb57'::uuid, 'card_description', 'Strabo called Rudiae a Greek city. In the immediate outskirts of Lecce, its remains still show traces of an amphitheatre, a necropolis and two city walls built of tuff.'), ('40acede4-eb32-4515-9ca4-b44145280678'::uuid, 'card_description', NULL), ('40fc1723-7365-4fcc-aab8-46f47e4eff17'::uuid, 'card_description', 'The Devil''s Causeway is a Roman road in Northumberland: it branches off Dere Street north of Corbridge and runs approximately 55 miles north to Berwick-upon-Tweed.'), ('417b5d77-c70a-40ad-adad-7f92ef1a0544'::uuid, 'card_description', NULL), ('418f6d87-0fc3-4eb6-a310-e45a1fb43a3d'::uuid, 'card_description', 'The Asclepieion of Pergamon was a healing temple for Asclepius and Hygieia, founded in the mid-4th century BCE as a modest spring shrine and built up over roughly eight centuries.'), ('42f11dde-ad7e-46e0-ab7b-37a7add49986'::uuid, 'card_description', 'Drusus founded the Ara trium Galliarum at Lugdunum, where the Rhone and Saone meet, as a sanctuary to Roma and Augustus. Its altar bore the names of 60 Gallic tribes.'), ('45ac8925-95ec-476a-9a36-9bbb650add84'::uuid, 'card_description', 'The House of Taga on Tinian held twelve prehistoric megaliths standing approximately 15 feet tall, each a base crowned by a hemispherical capstone. Only one still stands.'), ('45c293d7-6d69-47e5-adec-68b8e1ce6ec0'::uuid, 'card_description', NULL), ('4656cc72-cea3-407e-a61c-314450ff6c62'::uuid, 'card_description', 'Dating to approximately 50 BC, Ringsbury Camp is an Iron Age multivallate hillfort whose double banks were built from non-local limestone rubble. Its inner bank rises 5 metres high.'), ('46838746-5160-40bb-a0e7-5bb88bd33db9'::uuid, 'card_description', 'Occupied from around 500 BC, Dzibilnocac grew into a Maya city whose Chenes facades are elaborately decorated, while the main Palace carries a distinct Rio Bec design.'), ('46958435-223f-4648-93cc-153479b9c41c'::uuid, 'card_description', 'The Peterborough Petroglyphs, cut in the pre-Columbian era, are the largest collection of First Nations rock carvings in Ontario: shamans, animals, reptiles, possibly the Great Spirit.'), ('47c37ef9-98ee-41d8-879b-e78db06295da'::uuid, 'card_description', 'Phoenicians from Tyre revived Kition in the 9th century BC. Its Bamboula acropolis still shows ship sheds for triremes and a sanctuary dating to at least the 9th century BC.'), ('480b7897-a76a-406c-9991-7c1c8228f905'::uuid, 'card_description', 'Vrelo Šarkamen spans 25 hectares on the slopes of Deli Jovan in eastern Serbia, a Roman residential and memorial complex with a mausoleum. Only ruins remain today.'), ('489ca9da-126d-463b-b792-a1b39a555e3e'::uuid, 'card_description', 'Treva is the historical name of a Roman-era settlement in Germany, first recorded by Claudius Ptolemy in the 2nd century AD. Under Augustus, Roman forces reached the Elbe.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s032-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
